-- Seed data: 200 sentence prompts for the advanced level (10 per category), published.
-- Safe to re-run: a row is skipped when the same sentence already exists for that level and category.
-- Run in the Supabase SQL editor after migrations 0003 and 0004.

insert into public.prompts (writing_type, title, prompt_text, hint, difficulty, category, is_published)
select 'sentence'::public.writing_type, left(v.vietnamese, 80), v.vietnamese, v.hint, v.level, v.category, true
from (values
  ('advanced', 'personal-communication', 'Dù bất đồng về kết quả, hai bên vẫn cố gắng duy trì cuộc đối thoại một cách tôn trọng.', 'respectful dialogue, disagreement'),
  ('advanced', 'personal-communication', 'Cách diễn đạt thiếu rõ ràng đôi khi khiến một lời góp ý thiện chí bị hiểu thành lời chỉ trích.', 'ambiguous wording, criticism'),
  ('advanced', 'personal-communication', 'Thay vì phản ứng ngay lập tức, cô ấy dành thời gian xác định điều gì thực sự khiến mình khó chịu.', 'identify source of frustration'),
  ('advanced', 'personal-communication', 'Giao tiếp hiệu quả không chỉ phụ thuộc vào điều ta nói mà còn vào cách người khác tiếp nhận thông điệp.', 'communication, reception'),
  ('advanced', 'personal-communication', 'Anh ấy nhận ra rằng sự im lặng kéo dài có thể làm vấn đề trở nên nghiêm trọng hơn.', 'prolonged silence'),
  ('advanced', 'personal-communication', 'Một cuộc trao đổi thẳng thắn sẽ hữu ích hơn nếu mỗi người sẵn sàng xem xét giả định của mình.', 'examine assumptions'),
  ('advanced', 'personal-communication', 'Khi truyền đạt thông tin nhạy cảm, người nói cần cân nhắc cả thời điểm lẫn bối cảnh.', 'sensitive information, context'),
  ('advanced', 'personal-communication', 'Việc thừa nhận mình chưa hiểu rõ đôi khi giúp cuộc thảo luận tiến triển nhanh hơn.', 'admit uncertainty'),
  ('advanced', 'personal-communication', 'Thông điệp được cá nhân hóa có thể tạo cảm giác gần gũi, miễn là không xâm phạm quyền riêng tư.', 'personalized message, privacy'),
  ('advanced', 'personal-communication', 'Duy trì quan hệ lâu dài đòi hỏi khả năng xử lý bất đồng mà không làm tổn hại lòng tin.', 'manage disagreement, trust'),
  ('advanced', 'everyday-life', 'Việc tối giản đồ đạc chỉ bền vững khi thói quen mua sắm cũng thay đổi theo.', 'minimalism, shopping habits'),
  ('advanced', 'everyday-life', 'Dù lịch trình dày đặc, cô ấy vẫn dành thời gian nghỉ ngắn để tránh kiệt sức.', 'busy schedule, burnout'),
  ('advanced', 'everyday-life', 'Một kế hoạch sinh hoạt linh hoạt cần đủ cấu trúc để giữ nhịp nhưng không quá cứng nhắc.', 'flexible routine'),
  ('advanced', 'everyday-life', 'Thay vì cố hoàn thành mọi việc cùng lúc, tôi phân loại nhiệm vụ theo mức độ quan trọng.', 'prioritize tasks'),
  ('advanced', 'everyday-life', 'Những thói quen nhỏ lặp lại mỗi ngày thường tạo ra tác động lớn hơn các nỗ lực nhất thời.', 'small habits, long-term impact'),
  ('advanced', 'everyday-life', 'Chia sẻ trách nhiệm trong gia đình giúp giảm gánh nặng và hạn chế mâu thuẫn không cần thiết.', 'share responsibilities'),
  ('advanced', 'everyday-life', 'Việc chuẩn bị trước không loại bỏ mọi bất ngờ, nhưng giúp chúng ta ứng phó bình tĩnh hơn.', 'prepare for uncertainty'),
  ('advanced', 'everyday-life', 'Một không gian sống tiện nghi nên phản ánh nhu cầu thực tế thay vì chạy theo xu hướng.', 'practical living space'),
  ('advanced', 'everyday-life', 'Cân bằng giữa năng suất và nghỉ ngơi đòi hỏi mỗi người hiểu rõ giới hạn của bản thân.', 'productivity, rest'),
  ('advanced', 'everyday-life', 'Thay đổi nếp sống thường khó duy trì nếu mục tiêu quá lớn và thiếu những bước cụ thể.', 'sustainable change'),
  ('advanced', 'transportation-travel', 'Việc mở rộng giao thông công cộng chỉ phát huy hiệu quả khi các tuyến được kết nối thuận tiện.', 'integrated public transit'),
  ('advanced', 'transportation-travel', 'Dù lịch trình được lên kế hoạch kỹ, du khách vẫn nên dự phòng thời gian cho những tình huống bất ngờ.', 'plan for contingencies'),
  ('advanced', 'transportation-travel', 'Sự phát triển du lịch có thể thúc đẩy kinh tế địa phương nhưng cũng gây áp lực lên hạ tầng.', 'tourism, infrastructure pressure'),
  ('advanced', 'transportation-travel', 'Lựa chọn phương tiện ít phát thải cần đi kèm hệ thống đủ tin cậy để người dân sử dụng thường xuyên.', 'low-emission transport'),
  ('advanced', 'transportation-travel', 'Một điểm đến hấp dẫn không nhất thiết phải nổi tiếng nếu du khách hiểu cách khám phá có trách nhiệm.', 'responsible exploration'),
  ('advanced', 'transportation-travel', 'Những thay đổi nhỏ trong quy hoạch có thể cải thiện đáng kể khả năng tiếp cận của người khuyết tật.', 'accessible urban planning'),
  ('advanced', 'transportation-travel', 'Khi đặt vé qua nhiều đơn vị khác nhau, hành khách cần kiểm tra kỹ điều kiện đổi và hoàn vé.', 'change and refund terms'),
  ('advanced', 'transportation-travel', 'Tắc nghẽn giao thông không chỉ làm mất thời gian mà còn ảnh hưởng đến sức khỏe và năng suất lao động.', 'traffic congestion, productivity'),
  ('advanced', 'transportation-travel', 'Bảo tồn cảnh quan tự nhiên đòi hỏi giới hạn lượng khách ở những khu vực dễ bị tổn thương.', 'protect landscapes'),
  ('advanced', 'transportation-travel', 'Một chuyến đi đáng nhớ đôi khi đến từ những cuộc gặp gỡ ngoài dự kiến hơn là lịch trình hoàn hảo.', 'unexpected encounters'),
  ('advanced', 'school-education', 'Đánh giá năng lực toàn diện cần kết hợp kết quả thi với quá trình học tập và khả năng vận dụng kiến thức.', 'comprehensive assessment'),
  ('advanced', 'school-education', 'Một chương trình giáo dục công bằng phải tính đến sự khác biệt về điều kiện tiếp cận tài liệu và công nghệ.', 'equitable access'),
  ('advanced', 'school-education', 'Việc khuyến khích học sinh tranh luận chỉ hiệu quả khi lớp học tạo được môi trường an toàn cho ý kiến trái chiều.', 'safe classroom debate'),
  ('advanced', 'school-education', 'Thay vì ghi nhớ máy móc, người học nên được hướng dẫn liên hệ khái niệm mới với tình huống thực tế.', 'apply knowledge'),
  ('advanced', 'school-education', 'Công nghệ giáo dục có thể cá nhân hóa trải nghiệm học tập nhưng không thể thay thế hoàn toàn sự hướng dẫn của giáo viên.', 'personalized learning, teacher guidance'),
  ('advanced', 'school-education', 'Phản hồi có tính xây dựng cần cụ thể, kịp thời và tập trung vào cách cải thiện thay vì gắn nhãn người học.', 'constructive feedback'),
  ('advanced', 'school-education', 'Khoảng cách thành tích giữa các nhóm học sinh thường phản ánh nhiều yếu tố ngoài nỗ lực cá nhân.', 'achievement gap'),
  ('advanced', 'school-education', 'Một bài nghiên cứu thuyết phục phải phân biệt rõ bằng chứng, diễn giải và giả định của tác giả.', 'evidence, interpretation, assumption'),
  ('advanced', 'school-education', 'Học tập suốt đời trở nên cần thiết khi kỹ năng nghề nghiệp nhanh chóng mất đi tính cập nhật.', 'lifelong learning'),
  ('advanced', 'school-education', 'Tư duy phản biện phát triển tốt hơn khi người học được phép sửa đổi quan điểm trước bằng chứng mới.', 'revise views, evidence'),
  ('advanced', 'work-business', 'Tăng trưởng doanh thu sẽ khó duy trì nếu doanh nghiệp bỏ qua chất lượng dịch vụ và lòng tin của khách hàng.', 'sustainable revenue'),
  ('advanced', 'work-business', 'Một chiến lược mở rộng thị trường cần dựa trên dữ liệu đáng tin cậy thay vì chỉ dựa vào sự lạc quan.', 'market expansion, reliable data'),
  ('advanced', 'work-business', 'Việc phân quyền có thể đẩy nhanh quyết định, miễn là trách nhiệm và tiêu chí đánh giá được xác định rõ.', 'delegation, accountability'),
  ('advanced', 'work-business', 'Khi mục tiêu giữa các phòng ban xung đột, lãnh đạo cần làm rõ ưu tiên chung trước khi phân bổ nguồn lực.', 'cross-department priorities'),
  ('advanced', 'work-business', 'Tự động hóa chỉ tạo giá trị lâu dài nếu nhân viên được đào tạo để thích nghi với quy trình mới.', 'automation, staff training'),
  ('advanced', 'work-business', 'Một văn hóa làm việc lành mạnh khuyến khích phản biện mà không biến bất đồng chuyên môn thành xung đột cá nhân.', 'healthy work culture'),
  ('advanced', 'work-business', 'Doanh nghiệp cần cân bằng áp lực giảm chi phí với nghĩa vụ duy trì điều kiện làm việc an toàn.', 'cost reduction, safety'),
  ('advanced', 'work-business', 'Dữ liệu khách hàng có thể hỗ trợ quyết định kinh doanh nhưng phải được xử lý minh bạch và có trách nhiệm.', 'customer data, transparency'),
  ('advanced', 'work-business', 'Kế hoạch dự phòng hữu ích nhất khi được kiểm tra định kỳ thay vì chỉ tồn tại trên giấy.', 'contingency plan'),
  ('advanced', 'work-business', 'Hiệu quả của một cuộc họp nên được đo bằng quyết định và hành động tiếp theo, không phải thời lượng thảo luận.', 'meeting outcomes'),
  ('advanced', 'public-services', 'Dịch vụ công chỉ thực sự thuận tiện khi quy trình số hóa không loại trừ người thiếu kỹ năng công nghệ.', 'digital inclusion'),
  ('advanced', 'public-services', 'Việc công khai tiêu chí xử lý hồ sơ giúp giảm nghi ngờ và tạo điều kiện để người dân giám sát.', 'transparent criteria'),
  ('advanced', 'public-services', 'Một hệ thống phản hồi hiệu quả cần cho người gửi biết ý kiến của họ được tiếp nhận và giải quyết ra sao.', 'feedback process'),
  ('advanced', 'public-services', 'Khi nguồn lực hạn chế, cơ quan công quyền nên ưu tiên dịch vụ dựa trên mức độ cấp thiết và lợi ích cộng đồng.', 'prioritize public resources'),
  ('advanced', 'public-services', 'Thiết kế đô thị bao trùm đòi hỏi xem xét nhu cầu của người cao tuổi, trẻ em và người khuyết tật.', 'inclusive urban design'),
  ('advanced', 'public-services', 'Cải cách thủ tục sẽ khó đạt kết quả nếu các đơn vị liên quan vẫn sử dụng quy trình và dữ liệu không tương thích.', 'interoperable systems'),
  ('advanced', 'public-services', 'Minh bạch không chỉ là công bố thông tin mà còn là trình bày thông tin theo cách công chúng có thể hiểu.', 'public transparency'),
  ('advanced', 'public-services', 'Đầu tư vào bảo trì cơ sở hạ tầng thường ít gây chú ý hơn xây mới nhưng có thể tiết kiệm chi phí lâu dài.', 'infrastructure maintenance'),
  ('advanced', 'public-services', 'Niềm tin của người dân tăng lên khi quyết định hành chính được giải thích nhất quán và có thể kiểm chứng.', 'accountability, public trust'),
  ('advanced', 'public-services', 'Đánh giá chất lượng dịch vụ công nên kết hợp số liệu vận hành với trải nghiệm thực tế của người sử dụng.', 'service quality metrics'),
  ('advanced', 'health-medicine', 'Thông tin sức khỏe trên mạng cần được đánh giá dựa trên chất lượng bằng chứng chứ không phải mức độ lan truyền.', 'evaluate health evidence'),
  ('advanced', 'health-medicine', 'Một kế hoạch chăm sóc hiệu quả phải phù hợp với hoàn cảnh, khả năng tuân thủ và ưu tiên của từng người.', 'individualized care'),
  ('advanced', 'health-medicine', 'Phòng bệnh ở cấp cộng đồng đòi hỏi phối hợp giữa giáo dục, môi trường sống và khả năng tiếp cận dịch vụ y tế.', 'community prevention'),
  ('advanced', 'health-medicine', 'Việc giải thích rủi ro bằng ngôn ngữ dễ hiểu giúp bệnh nhân tham gia chủ động hơn vào quyết định điều trị.', 'informed treatment decisions'),
  ('advanced', 'health-medicine', 'Không nên xem một kết quả nghiên cứu riêng lẻ là kết luận cuối cùng khi bằng chứng khoa học vẫn đang phát triển.', 'evolving scientific evidence'),
  ('advanced', 'health-medicine', 'Sức khỏe tinh thần chịu ảnh hưởng từ điều kiện xã hội nên không thể chỉ được giải quyết bằng nỗ lực cá nhân.', 'social determinants, mental health'),
  ('advanced', 'health-medicine', 'Các chương trình can thiệp cần được đánh giá định kỳ để xác định liệu lợi ích có vượt quá chi phí hay không.', 'evaluate interventions'),
  ('advanced', 'health-medicine', 'Khuyến nghị y tế cần phân biệt rõ giữa mối liên hệ thống kê và quan hệ nhân quả.', 'correlation, causation'),
  ('advanced', 'health-medicine', 'Chính sách chăm sóc dự phòng có thể giảm áp lực cho bệnh viện nếu người dân tiếp cận được từ sớm.', 'preventive care access'),
  ('advanced', 'health-medicine', 'Giao tiếp đồng cảm giúp nhân viên y tế hiểu mối lo của bệnh nhân mà không làm giảm tính chính xác chuyên môn.', 'empathetic communication'),
  ('advanced', 'shopping-money', 'Quyết định mua sắm hợp lý cần tính đến tổng chi phí sở hữu chứ không chỉ giá niêm yết ban đầu.', 'total ownership cost'),
  ('advanced', 'shopping-money', 'Các chương trình giảm giá có thể thúc đẩy tiêu dùng bốc đồng nếu khách hàng không xác định nhu cầu từ trước.', 'impulse buying'),
  ('advanced', 'shopping-money', 'Một ngân sách thực tế nên dành khoản dự phòng cho những chi phí bất thường thay vì giả định mọi tháng đều giống nhau.', 'emergency fund'),
  ('advanced', 'shopping-money', 'Đánh giá độ bền và khả năng sửa chữa có thể giúp người tiêu dùng giảm chi phí trong dài hạn.', 'durability, repairability'),
  ('advanced', 'shopping-money', 'Sự tiện lợi của thanh toán số cần đi kèm biện pháp bảo vệ người dùng trước gian lận và lạm dụng dữ liệu.', 'digital payment security'),
  ('advanced', 'shopping-money', 'Người mua nên xem xét điều kiện hoàn trả trước khi đặt hàng từ những nhà bán lẻ chưa quen thuộc.', 'return policy'),
  ('advanced', 'shopping-money', 'Quảng cáo cá nhân hóa khiến việc phân biệt nhu cầu thật với mong muốn do tiếp thị tạo ra trở nên khó hơn.', 'personalized advertising'),
  ('advanced', 'shopping-money', 'Một quyết định đầu tư cá nhân cần phản ánh khả năng chấp nhận rủi ro và mục tiêu theo thời gian.', 'risk tolerance'),
  ('advanced', 'shopping-money', 'Minh bạch về phí phát sinh giúp khách hàng so sánh sản phẩm dựa trên chi phí thực tế.', 'hidden fees'),
  ('advanced', 'shopping-money', 'Tiết kiệm bền vững thường bắt đầu từ việc hiểu dòng tiền thay vì cắt giảm mọi khoản chi một cách máy móc.', 'understand cash flow'),
  ('advanced', 'food-drink', 'Việc bảo tồn món ăn truyền thống cần thích nghi với điều kiện hiện đại mà không làm mất đi ý nghĩa văn hóa.', 'preserve culinary heritage'),
  ('advanced', 'food-drink', 'Một thực đơn cân bằng không nhất thiết loại bỏ hoàn toàn món yêu thích mà chú trọng khẩu phần và sự đa dạng.', 'balanced diet'),
  ('advanced', 'food-drink', 'Nguồn gốc nguyên liệu ngày càng ảnh hưởng đến quyết định của thực khách quan tâm đến môi trường.', 'ingredient origins'),
  ('advanced', 'food-drink', 'Nhà hàng có thể giảm lãng phí thực phẩm bằng cách dự báo nhu cầu chính xác và điều chỉnh khẩu phần.', 'reduce food waste'),
  ('advanced', 'food-drink', 'Sự phổ biến toàn cầu của một món ăn đôi khi khiến phiên bản địa phương bị đơn giản hóa để phù hợp thị hiếu.', 'global popularity, local versions'),
  ('advanced', 'food-drink', 'Kỹ thuật chế biến không chỉ thay đổi hương vị mà còn ảnh hưởng đến kết cấu và giá trị dinh dưỡng.', 'cooking techniques'),
  ('advanced', 'food-drink', 'Đánh giá một nền ẩm thực qua vài món nổi tiếng dễ bỏ qua sự đa dạng giữa các vùng và cộng đồng.', 'regional diversity'),
  ('advanced', 'food-drink', 'Việc ghi nhãn dị ứng rõ ràng giúp thực khách lựa chọn an toàn hơn khi dùng bữa ngoài nhà.', 'allergen labeling'),
  ('advanced', 'food-drink', 'Nông nghiệp theo mùa có thể giảm áp lực vận chuyển nếu chuỗi cung ứng được tổ chức phù hợp.', 'seasonal agriculture'),
  ('advanced', 'food-drink', 'Chia sẻ bữa ăn tạo cơ hội kết nối xã hội, nhưng thói quen ăn uống vẫn khác nhau theo hoàn cảnh cá nhân.', 'shared meals, individual needs'),
  ('advanced', 'entertainment-leisure', 'Giải trí có giá trị không chỉ vì giúp thư giãn mà còn vì mở rộng góc nhìn về trải nghiệm con người.', 'human experience'),
  ('advanced', 'entertainment-leisure', 'Nền tảng phát trực tuyến tạo nhiều lựa chọn hơn nhưng thuật toán đề xuất có thể thu hẹp sự đa dạng nội dung.', 'recommendation algorithms'),
  ('advanced', 'entertainment-leisure', 'Một lễ hội thành công cần cân bằng trải nghiệm của khách tham dự với đời sống thường ngày của cư dân địa phương.', 'festival, residents'),
  ('advanced', 'entertainment-leisure', 'Việc biến sở thích thành công việc có thể đem lại thu nhập nhưng cũng làm thay đổi cảm giác tự do ban đầu.', 'hobby, profession'),
  ('advanced', 'entertainment-leisure', 'Các tác phẩm gây tranh luận thường buộc khán giả phân biệt giữa ý định của nghệ sĩ và cách công chúng diễn giải.', 'artist intent, interpretation'),
  ('advanced', 'entertainment-leisure', 'Không gian công cộng dành cho hoạt động văn hóa giúp những nhóm ít có cơ hội tiếp cận nghệ thuật tham gia nhiều hơn.', 'public cultural spaces'),
