  ('advanced', 'religion-spirituality', 'Đối thoại giữa các truyền thống tín ngưỡng cần tránh giả định rằng mọi thành viên đều thực hành niềm tin theo cùng một cách.', 'religious diversity'),
  ('advanced', 'religion-spirituality', 'Thực hành chiêm nghiệm có thể giúp một số người hiểu rõ giá trị cá nhân nhưng không thay thế việc giải quyết vấn đề thực tế.', 'reflection, practical problems'),
  ('advanced', 'religion-spirituality', 'Không gian tôn giáo vừa lưu giữ di sản tinh thần vừa phản ánh lịch sử và đời sống của cộng đồng.', 'religious heritage'),
  ('advanced', 'religion-spirituality', 'Tôn trọng tự do tín ngưỡng bao gồm cả quyền thay đổi niềm tin hoặc không theo một tôn giáo nào.', 'freedom of belief'),
  ('advanced', 'religion-spirituality', 'Các hoạt động thiện nguyện có sức lan tỏa hơn khi lòng trắc ẩn được chuyển thành hỗ trợ lâu dài và có tổ chức.', 'organized charity'),
  ('advanced', 'religion-spirituality', 'Nghi lễ truyền thống có thể duy trì cảm giác gắn kết ngay cả khi ý nghĩa của chúng thay đổi qua các thế hệ.', 'ritual, generational change'),
  ('advanced', 'religion-spirituality', 'Sự khác biệt trong niềm tin không nhất thiết dẫn đến chia rẽ nếu các bên thống nhất những nguyên tắc chung về phẩm giá.', 'dignity, belief differences'),
  ('advanced', 'religion-spirituality', 'Việc nghiên cứu tôn giáo cần phân biệt giữa mô tả thực hành và đánh giá niềm tin của người tham gia.', 'describe versus judge'),
  ('advanced', 'religion-spirituality', 'Đời sống tinh thần của mỗi người thường chịu ảnh hưởng đồng thời từ gia đình, cộng đồng và trải nghiệm riêng.', 'personal spirituality'),
  ('advanced', 'religion-spirituality', 'Một xã hội hòa hợp không đòi hỏi mọi người có cùng niềm tin mà cần bảo đảm họ được đối xử công bằng.', 'equal treatment'),
  ('advanced', 'law-justice', 'Nguyên tắc bình đẳng trước pháp luật chỉ có ý nghĩa khi mọi người có khả năng tiếp cận cơ chế bảo vệ quyền lợi.', 'access to justice'),
  ('advanced', 'law-justice', 'Quy định rõ ràng giúp giảm tranh chấp nhưng vẫn cần cách áp dụng linh hoạt trước những tình huống đặc biệt.', 'clear rules, exceptional cases'),
  ('advanced', 'law-justice', 'Một hệ thống tư pháp đáng tin cậy phải bảo đảm cả tính độc lập lẫn khả năng giải trình về quyết định.', 'judicial independence'),
  ('advanced', 'law-justice', 'Việc thu thập dữ liệu phục vụ điều tra cần được cân bằng với quyền riêng tư và các biện pháp bảo vệ phù hợp.', 'privacy, investigation'),
  ('advanced', 'law-justice', 'Hòa giải có thể tiết kiệm thời gian trong một số tranh chấp nhưng không nên thay thế bảo vệ quyền cơ bản.', 'mediation, fundamental rights'),
  ('advanced', 'law-justice', 'Phổ biến pháp luật hiệu quả đòi hỏi ví dụ thực tế và ngôn ngữ dễ hiểu thay vì chỉ công bố văn bản chuyên môn.', 'accessible legal education'),
  ('advanced', 'law-justice', 'Chế tài quá nghiêm khắc không nhất thiết ngăn vi phạm nếu khả năng phát hiện và thực thi còn thấp.', 'deterrence, enforcement'),
  ('advanced', 'law-justice', 'Hợp đồng công bằng cần phân bổ rủi ro minh bạch thay vì chuyển toàn bộ trách nhiệm sang bên yếu thế.', 'fair contracts'),
  ('advanced', 'law-justice', 'Bằng chứng cần được đánh giá theo độ tin cậy và ngữ cảnh chứ không chỉ theo số lượng tài liệu.', 'evidence reliability'),
  ('advanced', 'law-justice', 'Niềm tin vào pháp luật tăng lên khi quy trình khiếu nại có thể tiếp cận và kết quả được giải thích rõ ràng.', 'accessible appeals'),
  ('advanced', 'philosophy-ethics', 'Một lựa chọn có thể đem lại lợi ích tổng thể nhưng vẫn gây ra bất công nghiêm trọng cho một nhóm nhỏ.', 'aggregate benefit, minority harm'),
  ('advanced', 'philosophy-ethics', 'Ý định tốt không tự động biện minh cho hậu quả có thể dự đoán của một hành động.', 'intentions and consequences'),
  ('advanced', 'philosophy-ethics', 'Trách nhiệm đạo đức trở nên phức tạp khi cá nhân phải lựa chọn giữa những nghĩa vụ đều đáng được coi trọng.', 'competing duties'),
  ('advanced', 'philosophy-ethics', 'Sự trung thực cần đi cùng lòng trắc ẩn để việc nói thật không trở thành cái cớ gây tổn thương không cần thiết.', 'honesty, compassion'),
  ('advanced', 'philosophy-ethics', 'Một nguyên tắc chỉ đáng tin cậy khi chúng ta sẵn sàng áp dụng nó cả trong trường hợp bất lợi cho mình.', 'consistent principles'),
  ('advanced', 'philosophy-ethics', 'Tự do cá nhân cần được cân nhắc với tác động mà hành vi của một người gây ra cho người khác.', 'individual freedom, social impact'),
  ('advanced', 'philosophy-ethics', 'Việc đánh giá một quyết định nên xem xét cả quy trình lựa chọn lẫn kết quả cuối cùng.', 'process and outcome'),
  ('advanced', 'philosophy-ethics', 'Thừa nhận sự bất định không phải là từ bỏ phán đoán mà là giới hạn mức độ chắc chắn của kết luận.', 'uncertainty, judgment'),
  ('advanced', 'philosophy-ethics', 'Công bằng đòi hỏi chúng ta xem xét hoàn cảnh khác nhau thay vì chỉ áp dụng một công thức giống nhau cho mọi người.', 'fairness, differing circumstances'),
  ('advanced', 'philosophy-ethics', 'Suy ngẫm đạo đức có giá trị khi nó dẫn đến hành động nhất quán chứ không chỉ dừng lại ở lời nói.', 'ethical reflection, action')
) as v(level, category, vietnamese, hint)
where not exists (
  select 1 from public.prompts p
  where p.writing_type = 'sentence'
    and p.difficulty = v.level
    and p.category = v.category
    and p.prompt_text = v.vietnamese
);

-- Accepted answers with grammar notes for the 200 advanced sentences above (2 answers per sentence).
-- Run AFTER the prompts above and migration 0008_accepted_answers.sql. Safe to re-run: a prompt that already has
-- answers keeps them, so anything an admin edited is never overwritten.
-- Each answer: {"text": a correct English sentence, "structureVi": grammar notes in Vietnamese, "structureEn": the same in English}.
insert into public.prompt_answers (prompt_id, answers)
select p.id, v.answers
from (values
  ('advanced', 'personal-communication', 'Dù bất đồng về kết quả, hai bên vẫn cố gắng duy trì cuộc đối thoại một cách tôn trọng.', $j$[{"text": "Although they disagree about the outcome, both sides are still trying to keep the dialogue respectful.", "structureVi": "Although + mệnh đề: mặc dù\ntry to + V: cố gắng làm gì", "structureEn": "Although + clause: contrast\ntry to + V: make an effort"}, {"text": "Despite their disagreement over the result, the two parties continue to maintain a respectful conversation.", "structureVi": "Despite + danh từ: mặc dù\nmaintain + danh từ: duy trì", "structureEn": "Despite + noun: contrast\nmaintain + noun: keep going"}]$j$::jsonb),
  ('advanced', 'personal-communication', 'Cách diễn đạt thiếu rõ ràng đôi khi khiến một lời góp ý thiện chí bị hiểu thành lời chỉ trích.', $j$[{"text": "Unclear wording can sometimes cause well-intentioned advice to be taken as criticism.", "structureVi": "cause + vật + to be + V3: khiến bị (bị động)\nwell-intentioned: thiện chí", "structureEn": "cause + thing + to be + V3: passive result\nwell-intentioned: meaning well"}, {"text": "Vague phrasing sometimes makes a kind suggestion sound like a criticism.", "structureVi": "make + vật + V: khiến\nsound like: nghe như", "structureEn": "make + thing + V: cause\nsound like: seem to be"}]$j$::jsonb),
  ('advanced', 'personal-communication', 'Thay vì phản ứng ngay lập tức, cô ấy dành thời gian xác định điều gì thực sự khiến mình khó chịu.', $j$[{"text": "Instead of reacting immediately, she took time to work out what was really bothering her.", "structureVi": "Instead of + V-ing: thay vì\nwhat + mệnh đề: điều gì", "structureEn": "Instead of + V-ing: rather than\nwhat + clause: noun clause"}, {"text": "Rather than responding straight away, she spent some time identifying what actually upset her.", "structureVi": "Rather than + V-ing: thay vì\nspend time + V-ing: dành thời gian", "structureEn": "Rather than + V-ing: instead of\nspend time + V-ing: use time doing"}]$j$::jsonb),
  ('advanced', 'personal-communication', 'Giao tiếp hiệu quả không chỉ phụ thuộc vào điều ta nói mà còn vào cách người khác tiếp nhận thông điệp.', $j$[{"text": "Effective communication depends not only on what we say but also on how others receive the message.", "structureVi": "not only A but also B: không chỉ A mà còn B\ndepend on: phụ thuộc vào", "structureEn": "not only A but also B: both\ndepend on: be determined by"}, {"text": "Communicating well is not just about what we say, but about how the message is received by others.", "structureVi": "not just A but B: không chỉ A mà còn B\nhow + mệnh đề: cách", "structureEn": "not just A but B: both\nhow + clause: manner"}]$j$::jsonb),
  ('advanced', 'personal-communication', 'Anh ấy nhận ra rằng sự im lặng kéo dài có thể làm vấn đề trở nên nghiêm trọng hơn.', $j$[{"text": "He realized that prolonged silence can make a problem more serious.", "structureVi": "realize that + mệnh đề: nhận ra rằng\nmake + vật + tính từ: khiến", "structureEn": "realize that + clause: come to understand\nmake + thing + adjective: cause"}, {"text": "He came to see that staying silent for a long time may make things worse.", "structureVi": "come to + V: dần nhận ra\nmake things worse: làm tệ hơn", "structureEn": "come to + V: gradually begin to\nmake things worse: aggravate"}]$j$::jsonb),
  ('advanced', 'personal-communication', 'Một cuộc trao đổi thẳng thắn sẽ hữu ích hơn nếu mỗi người sẵn sàng xem xét giả định của mình.', $j$[{"text": "A frank exchange will be more useful if each person is willing to examine their own assumptions.", "structureVi": "be willing to + V: sẵn sàng\nmore + tính từ: hơn", "structureEn": "be willing to + V: ready to\nmore + adjective: comparative"}, {"text": "An open discussion is more helpful when everyone is ready to question their own assumptions.", "structureVi": "be ready to + V: sẵn sàng\nquestion + danh từ: đặt câu hỏi về", "structureEn": "be ready to + V: prepared to\nquestion + noun: doubt"}]$j$::jsonb),
  ('advanced', 'personal-communication', 'Khi truyền đạt thông tin nhạy cảm, người nói cần cân nhắc cả thời điểm lẫn bối cảnh.', $j$[{"text": "When conveying sensitive information, speakers need to consider both the timing and the context.", "structureVi": "When + V-ing: khi làm gì\nboth A and B: cả A lẫn B", "structureEn": "When + V-ing: reduced clause\nboth A and B: two things"}, {"text": "Someone sharing delicate information should think about when and in what setting to do it.", "structureVi": "someone + V-ing: người đang\nin what setting: trong bối cảnh nào", "structureEn": "someone + V-ing: reduced relative clause\nin what setting: question phrase"}]$j$::jsonb),
  ('advanced', 'personal-communication', 'Việc thừa nhận mình chưa hiểu rõ đôi khi giúp cuộc thảo luận tiến triển nhanh hơn.', $j$[{"text": "Admitting that you haven't fully understood can sometimes help a discussion progress faster.", "structureVi": "V-ing làm chủ ngữ: thừa nhận\nhelp + vật + V: giúp", "structureEn": "V-ing as subject: admitting\nhelp + thing + V: assist"}, {"text": "Acknowledging that you're not entirely sure what is meant can sometimes speed up a discussion.", "structureVi": "acknowledge that: thừa nhận rằng\nspeed up: đẩy nhanh", "structureEn": "acknowledge that: admit\nspeed up: make faster"}]$j$::jsonb),
  ('advanced', 'personal-communication', 'Thông điệp được cá nhân hóa có thể tạo cảm giác gần gũi, miễn là không xâm phạm quyền riêng tư.', $j$[{"text": "Personalized messages can create a sense of closeness, as long as they don't invade people's privacy.", "structureVi": "as long as + mệnh đề: miễn là\na sense of: cảm giác", "structureEn": "as long as + clause: condition\na sense of: feeling of"}, {"text": "Tailored messages can make people feel close to you, provided that they do not intrude on privacy.", "structureVi": "provided that + mệnh đề: với điều kiện\nintrude on: xâm phạm", "structureEn": "provided that + clause: condition\nintrude on: invade"}]$j$::jsonb),
  ('advanced', 'personal-communication', 'Duy trì quan hệ lâu dài đòi hỏi khả năng xử lý bất đồng mà không làm tổn hại lòng tin.', $j$[{"text": "Maintaining a long-term relationship requires the ability to handle disagreements without damaging trust.", "structureVi": "V-ing làm chủ ngữ: duy trì\nwithout + V-ing: mà không", "structureEn": "V-ing as subject: maintaining\nwithout + V-ing: not causing"}, {"text": "Keeping a relationship going for years takes the skill to deal with conflict without harming trust.", "structureVi": "take + danh từ: đòi hỏi\nthe skill to + V: khả năng", "structureEn": "take + noun: require\nthe skill to + V: ability"}]$j$::jsonb),
  ('advanced', 'everyday-life', 'Việc tối giản đồ đạc chỉ bền vững khi thói quen mua sắm cũng thay đổi theo.', $j$[{"text": "Minimalism with belongings is only sustainable if shopping habits change as well.", "structureVi": "only + tính từ: chỉ khi\nif + mệnh đề: nếu", "structureEn": "only + adjective: limited condition\nif + clause: condition"}, {"text": "Owning fewer things lasts only when the way you shop changes too.", "structureVi": "V-ing làm chủ ngữ: sở hữu ít\nwhen + mệnh đề: khi", "structureEn": "V-ing as subject: owning fewer\nwhen + clause: condition"}]$j$::jsonb),
  ('advanced', 'everyday-life', 'Dù lịch trình dày đặc, cô ấy vẫn dành thời gian nghỉ ngắn để tránh kiệt sức.', $j$[{"text": "Despite her packed schedule, she still takes short breaks to avoid burnout.", "structureVi": "Despite + danh từ: mặc dù\nto avoid + danh từ: để tránh", "structureEn": "Despite + noun: contrast\nto avoid + noun: purpose"}, {"text": "Even though her schedule is full, she takes brief rests so that she doesn't burn out.", "structureVi": "Even though + mệnh đề: mặc dù\nso that + mệnh đề: để mà", "structureEn": "Even though + clause: contrast\nso that + clause: purpose"}]$j$::jsonb),
  ('advanced', 'everyday-life', 'Một kế hoạch sinh hoạt linh hoạt cần đủ cấu trúc để giữ nhịp nhưng không quá cứng nhắc.', $j$[{"text": "A flexible daily plan needs enough structure to keep a rhythm but not so much that it becomes rigid.", "structureVi": "enough + danh từ + to + V: đủ để\nnot so much that: không quá đến mức", "structureEn": "enough + noun + to + V: sufficient for\nnot so much that: limit"}, {"text": "A flexible routine should be structured enough to give you a rhythm without being too strict.", "structureVi": "tính từ + enough + to + V: đủ... để\nwithout + V-ing: mà không", "structureEn": "adjective + enough + to + V: sufficiently\nwithout + V-ing: not being"}]$j$::jsonb),
  ('advanced', 'everyday-life', 'Thay vì cố hoàn thành mọi việc cùng lúc, tôi phân loại nhiệm vụ theo mức độ quan trọng.', $j$[{"text": "Rather than trying to finish everything at once, I sort tasks by how important they are.", "structureVi": "Rather than + V-ing: thay vì\nhow + tính từ: mức độ", "structureEn": "Rather than + V-ing: instead of\nhow + adjective: degree"}, {"text": "Instead of attempting every job at the same time, I rank my tasks by their importance.", "structureVi": "Instead of + V-ing: thay vì\nrank A by B: xếp A theo B", "structureEn": "Instead of + V-ing: rather than\nrank A by B: order by"}]$j$::jsonb),
  ('advanced', 'everyday-life', 'Những thói quen nhỏ lặp lại mỗi ngày thường tạo ra tác động lớn hơn các nỗ lực nhất thời.', $j$[{"text": "Small habits repeated every day often have a bigger impact than short-lived efforts.", "structureVi": "Small habits repeated: rút gọn mệnh đề quan hệ\nbigger impact than: tác động lớn hơn", "structureEn": "Small habits repeated: reduced relative clause\nbigger impact than: comparison"}, {"text": "Little things you do daily usually matter more than one-off bursts of effort.", "structureVi": "things (that) you do: mệnh đề quan hệ lược that\nmatter more than: quan trọng hơn", "structureEn": "things (that) you do: relative clause\nmatter more than: comparative"}]$j$::jsonb),
  ('advanced', 'everyday-life', 'Chia sẻ trách nhiệm trong gia đình giúp giảm gánh nặng và hạn chế mâu thuẫn không cần thiết.', $j$[{"text": "Sharing responsibilities in the family reduces the burden and limits unnecessary conflicts.", "structureVi": "V-ing làm chủ ngữ: chia sẻ\nlimit + danh từ: hạn chế", "structureEn": "V-ing as subject: sharing\nlimit + noun: reduce"}, {"text": "When family members share duties, the load gets lighter and fewer pointless arguments arise.", "structureVi": "When + mệnh đề: khi\nfewer + danh từ đếm được: ít hơn", "structureEn": "When + clause: time\nfewer + countable noun: smaller number"}]$j$::jsonb),
  ('advanced', 'everyday-life', 'Việc chuẩn bị trước không loại bỏ mọi bất ngờ, nhưng giúp chúng ta ứng phó bình tĩnh hơn.', $j$[{"text": "Preparing in advance doesn't remove every surprise, but it helps us respond more calmly.", "structureVi": "V-ing làm chủ ngữ: chuẩn bị\nhelp + người + V: giúp", "structureEn": "V-ing as subject: preparing\nhelp + person + V: assist"}, {"text": "Being prepared won't eliminate all surprises, yet it lets us handle them with more composure.", "structureVi": "Being + V3: việc được chuẩn bị\nhandle: xử lý", "structureEn": "Being + V3: passive gerund\nhandle: deal with"}]$j$::jsonb),
  ('advanced', 'everyday-life', 'Một không gian sống tiện nghi nên phản ánh nhu cầu thực tế thay vì chạy theo xu hướng.', $j$[{"text": "A comfortable living space should reflect real needs rather than follow trends.", "structureVi": "should + V: nên\nrather than + V: thay vì", "structureEn": "should + V: advice\nrather than + V: instead of"}, {"text": "A home that is comfortable ought to suit how we actually live instead of chasing fashion.", "structureVi": "ought to + V: nên\ninstead of + V-ing: thay vì", "structureEn": "ought to + V: advice\ninstead of + V-ing: rather than"}]$j$::jsonb),
  ('advanced', 'everyday-life', 'Cân bằng giữa năng suất và nghỉ ngơi đòi hỏi mỗi người hiểu rõ giới hạn của bản thân.', $j$[{"text": "Balancing productivity and rest requires each person to understand their own limits.", "structureVi": "V-ing làm chủ ngữ: cân bằng\nrequire + người + to + V: đòi hỏi ai", "structureEn": "V-ing as subject: balancing\nrequire + person + to + V: need someone to"}, {"text": "To strike a balance between getting things done and resting, everyone has to know their limits well.", "structureVi": "strike a balance between: cân bằng\nhave to + V: phải", "structureEn": "strike a balance between: balance\nhave to + V: must"}]$j$::jsonb),
  ('advanced', 'everyday-life', 'Thay đổi nếp sống thường khó duy trì nếu mục tiêu quá lớn và thiếu những bước cụ thể.', $j$[{"text": "Lifestyle changes are often hard to sustain if the goal is too big and lacks concrete steps.", "structureVi": "if + mệnh đề: nếu\nlack + danh từ: thiếu", "structureEn": "if + clause: condition\nlack + noun: not have"}, {"text": "Changing the way you live is usually difficult to keep up when the target is too large and has no specific steps.", "structureVi": "difficult to + V: khó làm\nkeep up: duy trì", "structureEn": "difficult to + V: hard to do\nkeep up: maintain"}]$j$::jsonb),
  ('advanced', 'transportation-travel', 'Việc mở rộng giao thông công cộng chỉ phát huy hiệu quả khi các tuyến được kết nối thuận tiện.', $j$[{"text": "Expanding public transport is effective only when the routes are conveniently connected.", "structureVi": "V-ing làm chủ ngữ: mở rộng\nonly when + mệnh đề: chỉ khi", "structureEn": "V-ing as subject: expanding\nonly when + clause: limiting condition"}, {"text": "More public transit works well only if the lines link up conveniently.", "structureVi": "link up: kết nối\nonly if + mệnh đề: chỉ nếu", "structureEn": "link up: connect\nonly if + clause: sole condition"}]$j$::jsonb),
  ('advanced', 'transportation-travel', 'Dù lịch trình được lên kế hoạch kỹ, du khách vẫn nên dự phòng thời gian cho những tình huống bất ngờ.', $j$[{"text": "Even if their itinerary is carefully planned, travelers should still allow extra time for unexpected situations.", "structureVi": "Even if + mệnh đề: ngay cả khi\nallow time for: dự phòng thời gian", "structureEn": "Even if + clause: despite possibility\nallow time for: reserve time"}, {"text": "However well a trip is planned, tourists ought to leave some spare time in case something unexpected happens.", "structureVi": "However + trạng từ + mệnh đề: dù... đến đâu\nin case + mệnh đề: phòng khi", "structureEn": "However + adverb + clause: no matter how\nin case + clause: just in case"}]$j$::jsonb),
  ('advanced', 'transportation-travel', 'Sự phát triển du lịch có thể thúc đẩy kinh tế địa phương nhưng cũng gây áp lực lên hạ tầng.', $j$[{"text": "The growth of tourism can boost the local economy but also puts pressure on infrastructure.", "structureVi": "can + V: có thể\nput pressure on: gây áp lực lên", "structureEn": "can + V: possibility\nput pressure on: strain"}, {"text": "Tourism development may stimulate the regional economy while straining its infrastructure.", "structureVi": "may + V: có thể\nwhile + V-ing: trong khi", "structureEn": "may + V: possibility\nwhile + V-ing: at the same time"}]$j$::jsonb),
  ('advanced', 'transportation-travel', 'Lựa chọn phương tiện ít phát thải cần đi kèm hệ thống đủ tin cậy để người dân sử dụng thường xuyên.', $j$[{"text": "Choosing low-emission transport must go hand in hand with a system reliable enough for people to use regularly.", "structureVi": "go hand in hand with: đi đôi với\nenough for + người + to + V: đủ để", "structureEn": "go hand in hand with: accompany\nenough for + person + to + V: sufficient for"}, {"text": "Low-emission vehicles only work if the system is dependable enough that residents rely on it often.", "structureVi": "dependable enough that: đủ tin cậy để\nrely on: dựa vào", "structureEn": "dependable enough that: result clause\nrely on: depend on"}]$j$::jsonb),
  ('advanced', 'transportation-travel', 'Một điểm đến hấp dẫn không nhất thiết phải nổi tiếng nếu du khách hiểu cách khám phá có trách nhiệm.', $j$[{"text": "An attractive destination doesn't have to be famous as long as visitors know how to explore responsibly.", "structureVi": "not necessarily: không nhất thiết\nknow how to + V: biết cách", "structureEn": "not necessarily: not required\nknow how to + V: have the skill"}, {"text": "A place can be appealing without being well known if tourists understand how to explore it responsibly.", "structureVi": "without + being + V3: mà không\nunderstand how to + V: hiểu cách", "structureEn": "without + being + V3: passive gerund\nunderstand how to + V: know"}]$j$::jsonb),
  ('advanced', 'transportation-travel', 'Những thay đổi nhỏ trong quy hoạch có thể cải thiện đáng kể khả năng tiếp cận của người khuyết tật.', $j$[{"text": "Small changes in planning can significantly improve accessibility for people with disabilities.", "structureVi": "significantly + V: cải thiện đáng kể\npeople with disabilities: người khuyết tật", "structureEn": "significantly + V: adverb\npeople with disabilities: disabled people"}, {"text": "Minor adjustments to urban design can make a big difference to how easily disabled people get around.", "structureVi": "make a difference to: tạo khác biệt\nhow easily: dễ dàng đến mức nào", "structureEn": "make a difference to: affect\nhow easily: degree"}]$j$::jsonb),
  ('advanced', 'transportation-travel', 'Khi đặt vé qua nhiều đơn vị khác nhau, hành khách cần kiểm tra kỹ điều kiện đổi và hoàn vé.', $j$[{"text": "When booking tickets through several providers, passengers should read the change and refund conditions carefully.", "structureVi": "When + V-ing: khi làm gì\nthrough + danh từ: qua", "structureEn": "When + V-ing: reduced clause\nthrough + noun: via"}, {"text": "If you buy tickets from different companies, you ought to check the exchange and refund terms closely.", "structureVi": "If + hiện tại đơn, ought to + V: nếu\nexchange and refund terms: điều kiện đổi và hoàn", "structureEn": "If + present simple: condition\nexchange and refund terms: policy"}]$j$::jsonb),
  ('advanced', 'transportation-travel', 'Tắc nghẽn giao thông không chỉ làm mất thời gian mà còn ảnh hưởng đến sức khỏe và năng suất lao động.', $j$[{"text": "Traffic congestion not only wastes time but also affects people's health and labor productivity.", "structureVi": "not only A but also B: không chỉ A mà còn B\naffect + danh từ: ảnh hưởng", "structureEn": "not only A but also B: both\naffect + noun: influence"}, {"text": "Gridlock doesn't just cost people time; it also harms their health and reduces how productive workers are.", "structureVi": "not just A; also B: không chỉ A mà còn B\nhow + tính từ + mệnh đề: mức độ", "structureEn": "not just A; also B: both\nhow + adjective + clause: degree"}]$j$::jsonb),
  ('advanced', 'transportation-travel', 'Bảo tồn cảnh quan tự nhiên đòi hỏi giới hạn lượng khách ở những khu vực dễ bị tổn thương.', $j$[{"text": "Protecting natural landscapes requires limiting the number of visitors in vulnerable areas.", "structureVi": "V-ing làm chủ ngữ: bảo vệ\nrequire + V-ing: đòi hỏi", "structureEn": "V-ing as subject: protecting\nrequire + V-ing: need"}, {"text": "Preserving natural scenery means capping visitor numbers in fragile areas.", "structureVi": "mean + V-ing: có nghĩa là\ncap: đặt mức trần", "structureEn": "mean + V-ing: involve\ncap: set a limit"}]$j$::jsonb),
  ('advanced', 'transportation-travel', 'Một chuyến đi đáng nhớ đôi khi đến từ những cuộc gặp gỡ ngoài dự kiến hơn là lịch trình hoàn hảo.', $j$[{"text": "A memorable trip sometimes comes from unplanned encounters rather than a perfect itinerary.", "structureVi": "come from: đến từ\nrather than: hơn là", "structureEn": "come from: result from\nrather than: instead of"}, {"text": "Sometimes what makes a journey unforgettable is meeting people you didn't expect to, not a flawless schedule.", "structureVi": "what + V: điều khiến (chủ ngữ)\nnot A: chứ không phải A", "structureEn": "what + V: noun clause subject\nnot A: contrast"}]$j$::jsonb),
  ('advanced', 'school-education', 'Đánh giá năng lực toàn diện cần kết hợp kết quả thi với quá trình học tập và khả năng vận dụng kiến thức.', $j$[{"text": "A comprehensive assessment needs to combine exam results with the learning process and the ability to apply knowledge.", "structureVi": "combine A with B: kết hợp A với B\nthe ability to + V: khả năng", "structureEn": "combine A with B: mix\nthe ability to + V: capacity"}, {"text": "A thorough evaluation should look at test scores, the way a student learns, and how well they can use what they know.", "structureVi": "look at: xem xét\nhow well + mệnh đề: mức độ tốt", "structureEn": "look at: consider\nhow well + clause: degree"}]$j$::jsonb),
  ('advanced', 'school-education', 'Một chương trình giáo dục công bằng phải tính đến sự khác biệt về điều kiện tiếp cận tài liệu và công nghệ.', $j$[{"text": "A fair education program must take into account differences in access to materials and technology.", "structureVi": "take into account: tính đến\ndifferences in: sự khác biệt về", "structureEn": "take into account: consider\ndifferences in: variation in"}, {"text": "An equitable curriculum has to consider that students don't all have the same access to resources and technology.", "structureVi": "consider that + mệnh đề: xem xét việc\ndon't all: không phải tất cả", "structureEn": "consider that + clause: bear in mind\ndon't all: partial negation"}]$j$::jsonb),
  ('advanced', 'school-education', 'Việc khuyến khích học sinh tranh luận chỉ hiệu quả khi lớp học tạo được môi trường an toàn cho ý kiến trái chiều.', $j$[{"text": "Encouraging students to debate is effective only when the classroom creates a safe environment for opposing opinions.", "structureVi": "Encouraging: V-ing làm chủ ngữ\nonly when + mệnh đề: chỉ khi", "structureEn": "Encouraging: gerund subject\nonly when + clause: limiting condition"}, {"text": "Getting students to argue their views works only if the class feels safe for differing opinions.", "structureVi": "get + người + to + V: khiến ai\nfeel safe for: an toàn cho", "structureEn": "get + person + to + V: persuade\nfeel safe for: secure"}]$j$::jsonb),
  ('advanced', 'school-education', 'Thay vì ghi nhớ máy móc, người học nên được hướng dẫn liên hệ khái niệm mới với tình huống thực tế.', $j$[{"text": "Instead of memorizing mechanically, learners should be guided to connect new concepts to real situations.", "structureVi": "Instead of + V-ing: thay vì\nshould be + V3: nên được", "structureEn": "Instead of + V-ing: rather than\nshould be + V3: passive advice"}, {"text": "Rather than learning by rote, students ought to be shown how to relate new ideas to real-life cases.", "structureVi": "learn by rote: học vẹt\nrelate A to B: liên hệ A với B", "structureEn": "learn by rote: memorize mechanically\nrelate A to B: connect"}]$j$::jsonb),
  ('advanced', 'school-education', 'Công nghệ giáo dục có thể cá nhân hóa trải nghiệm học tập nhưng không thể thay thế hoàn toàn sự hướng dẫn của giáo viên.', $j$[{"text": "Educational technology can personalize the learning experience but cannot completely replace teachers' guidance.", "structureVi": "can + V: có thể\ncannot completely + V: không thể hoàn toàn", "structureEn": "can + V: ability\ncannot completely + V: partial negation"}, {"text": "Ed-tech can tailor learning to each person, yet it can't fully take the place of a teacher's guidance.", "structureVi": "tailor A to B: điều chỉnh A cho B\ntake the place of: thay thế", "structureEn": "tailor A to B: adapt\ntake the place of: replace"}]$j$::jsonb),
  ('advanced', 'school-education', 'Phản hồi có tính xây dựng cần cụ thể, kịp thời và tập trung vào cách cải thiện thay vì gắn nhãn người học.', $j$[{"text": "Constructive feedback should be specific, timely and focused on how to improve rather than labeling the learner.", "structureVi": "should be + tính từ: nên\nrather than + V-ing: thay vì", "structureEn": "should be + adjective: advice\nrather than + V-ing: instead of"}, {"text": "Helpful feedback has to be detailed and prompt, and it should explain how to get better instead of putting a label on the student.", "structureVi": "has to be: phải\ninstead of + V-ing: thay vì", "structureEn": "has to be: obligation\ninstead of + V-ing: rather than"}]$j$::jsonb),
  ('advanced', 'school-education', 'Khoảng cách thành tích giữa các nhóm học sinh thường phản ánh nhiều yếu tố ngoài nỗ lực cá nhân.', $j$[{"text": "The achievement gap between groups of students often reflects many factors beyond individual effort.", "structureVi": "the gap between: khoảng cách giữa\nbeyond + danh từ: vượt ra ngoài", "structureEn": "the gap between: difference\nbeyond + noun: outside of"}, {"text": "Differences in results among student groups frequently result from numerous things other than personal effort.", "structureVi": "result from: do bởi\nother than: ngoài ra", "structureEn": "result from: be caused by\nother than: apart from"}]$j$::jsonb),
  ('advanced', 'school-education', 'Một bài nghiên cứu thuyết phục phải phân biệt rõ bằng chứng, diễn giải và giả định của tác giả.', $j$[{"text": "A convincing research paper must clearly distinguish the author's evidence, interpretation and assumptions.", "structureVi": "distinguish A from B: phân biệt\nmust + V: phải", "structureEn": "distinguish A from B: tell apart\nmust + V: obligation"}, {"text": "A persuasive study needs to make clear what is evidence, what is interpretation and what is simply assumed by the author.", "structureVi": "make clear: làm rõ\nwhat is + V3: điều được", "structureEn": "make clear: clarify\nwhat is + V3: passive noun clause"}]$j$::jsonb),
  ('advanced', 'school-education', 'Học tập suốt đời trở nên cần thiết khi kỹ năng nghề nghiệp nhanh chóng mất đi tính cập nhật.', $j$[{"text": "Lifelong learning becomes necessary when professional skills quickly become outdated.", "structureVi": "become + tính từ: trở nên\nwhen + mệnh đề: khi", "structureEn": "become + adjective: change to\nwhen + clause: time"}, {"text": "Learning throughout life is essential now that job skills go out of date so fast.", "structureVi": "now that + mệnh đề: vì giờ đây\ngo out of date: lỗi thời", "structureEn": "now that + clause: since\ngo out of date: become obsolete"}]$j$::jsonb),
  ('advanced', 'school-education', 'Tư duy phản biện phát triển tốt hơn khi người học được phép sửa đổi quan điểm trước bằng chứng mới.', $j$[{"text": "Critical thinking develops better when learners are allowed to revise their views in light of new evidence.", "structureVi": "be allowed to + V: được phép\nin light of: dựa trên", "structureEn": "be allowed to + V: permission\nin light of: considering"}, {"text": "Students think more critically when they are free to change their minds because of new evidence.", "structureVi": "be free to + V: được tự do\nbecause of + danh từ: vì", "structureEn": "be free to + V: allowed to\nbecause of + noun: reason"}]$j$::jsonb),
  ('advanced', 'work-business', 'Tăng trưởng doanh thu sẽ khó duy trì nếu doanh nghiệp bỏ qua chất lượng dịch vụ và lòng tin của khách hàng.', $j$[{"text": "Revenue growth will be hard to sustain if a business ignores service quality and customer trust.", "structureVi": "be hard to + V: khó\nignore + danh từ: bỏ qua", "structureEn": "be hard to + V: difficult to\nignore + noun: disregard"}, {"text": "A company that overlooks service quality and customer confidence will struggle to keep growing its income.", "structureVi": "A company that + V: mệnh đề quan hệ\nstruggle to + V: vất vả để", "structureEn": "A company that + V: relative clause\nstruggle to + V: have difficulty"}]$j$::jsonb),
  ('advanced', 'work-business', 'Một chiến lược mở rộng thị trường cần dựa trên dữ liệu đáng tin cậy thay vì chỉ dựa vào sự lạc quan.', $j$[{"text": "A market expansion strategy should be based on reliable data rather than optimism alone.", "structureVi": "be based on: dựa trên\nrather than: hơn là", "structureEn": "be based on: rely on\nrather than: instead of"}, {"text": "Plans to enter new markets need to rest on trustworthy figures, not just on hope.", "structureVi": "rest on: dựa vào\nnot just: không chỉ", "structureEn": "rest on: depend on\nnot just: more than"}]$j$::jsonb),
  ('advanced', 'work-business', 'Việc phân quyền có thể đẩy nhanh quyết định, miễn là trách nhiệm và tiêu chí đánh giá được xác định rõ.', $j$[{"text": "Delegation can speed up decisions, provided that responsibilities and evaluation criteria are clearly defined.", "structureVi": "provided that + mệnh đề: miễn là\nbe defined: được xác định", "structureEn": "provided that + clause: condition\nbe defined: passive"}, {"text": "Handing over authority can make decisions faster as long as accountability and the standards for judging results are clear.", "structureVi": "as long as + mệnh đề: miễn là\nhand over: giao lại", "structureEn": "as long as + clause: condition\nhand over: pass on"}]$j$::jsonb),
  ('advanced', 'work-business', 'Khi mục tiêu giữa các phòng ban xung đột, lãnh đạo cần làm rõ ưu tiên chung trước khi phân bổ nguồn lực.', $j$[{"text": "When goals conflict between departments, leaders need to clarify shared priorities before allocating resources.", "structureVi": "When + mệnh đề: khi\nbefore + V-ing: trước khi", "structureEn": "When + clause: time\nbefore + V-ing: before + gerund"}, {"text": "If departments have clashing objectives, management must make common priorities clear before they distribute resources.", "structureVi": "clashing: xung đột\ndistribute: phân bổ", "structureEn": "clashing: conflicting\ndistribute: allocate"}]$j$::jsonb),
  ('advanced', 'work-business', 'Tự động hóa chỉ tạo giá trị lâu dài nếu nhân viên được đào tạo để thích nghi với quy trình mới.', $j$[{"text": "Automation creates long-term value only if employees are trained to adapt to the new processes.", "structureVi": "only if + mệnh đề: chỉ nếu\nbe trained to + V: được đào tạo để", "structureEn": "only if + clause: sole condition\nbe trained to + V: passive purpose"}, {"text": "Automating tasks brings lasting benefits only when staff learn how to adjust to the new workflow.", "structureVi": "V-ing làm chủ ngữ: tự động hóa\nlearn how to + V: học cách", "structureEn": "V-ing as subject: automating\nlearn how to + V: gain a skill"}]$j$::jsonb),
  ('advanced', 'work-business', 'Một văn hóa làm việc lành mạnh khuyến khích phản biện mà không biến bất đồng chuyên môn thành xung đột cá nhân.', $j$[{"text": "A healthy work culture encourages challenge without turning professional disagreements into personal conflicts.", "structureVi": "encourage + danh từ: khuyến khích\nwithout + V-ing: mà không", "structureEn": "encourage + noun: promote\nwithout + V-ing: not doing"}, {"text": "In a good workplace culture, people can question each other's ideas without professional differences becoming personal fights.", "structureVi": "In + danh từ: trong\nwithout + danh từ + V-ing: mà không", "structureEn": "In + noun: within\nwithout + noun + V-ing: absence"}]$j$::jsonb),
  ('advanced', 'work-business', 'Doanh nghiệp cần cân bằng áp lực giảm chi phí với nghĩa vụ duy trì điều kiện làm việc an toàn.', $j$[{"text": "Businesses need to balance the pressure to cut costs against the obligation to maintain safe working conditions.", "structureVi": "balance A against B: cân bằng\nthe obligation to + V: nghĩa vụ", "structureEn": "balance A against B: weigh\nthe obligation to + V: duty"}, {"text": "Companies must weigh the push to reduce expenses against their duty to keep workplaces safe.", "structureVi": "weigh A against B: cân nhắc\ntheir duty to + V: nghĩa vụ", "structureEn": "weigh A against B: compare\ntheir duty to + V: obligation"}]$j$::jsonb),
  ('advanced', 'work-business', 'Dữ liệu khách hàng có thể hỗ trợ quyết định kinh doanh nhưng phải được xử lý minh bạch và có trách nhiệm.', $j$[{"text": "Customer data can support business decisions, but it must be handled transparently and responsibly.", "structureVi": "can + V: có thể\nmust be + V3: phải được", "structureEn": "can + V: ability\nmust be + V3: passive obligation"}, {"text": "Information about customers can inform commercial choices, provided it is used openly and with care.", "structureVi": "inform: cung cấp thông tin cho\nprovided (that): miễn là", "structureEn": "inform: help shape\nprovided (that): condition"}]$j$::jsonb),
  ('advanced', 'work-business', 'Kế hoạch dự phòng hữu ích nhất khi được kiểm tra định kỳ thay vì chỉ tồn tại trên giấy.', $j$[{"text": "A contingency plan is most useful when it is tested regularly rather than existing only on paper.", "structureVi": "most + tính từ: nhất\nrather than + V-ing: thay vì", "structureEn": "most + adjective: superlative\nrather than + V-ing: instead of"}, {"text": "Backup plans are of greatest value if they are checked from time to time instead of merely sitting in a document.", "structureVi": "of value: có giá trị\nfrom time to time: định kỳ", "structureEn": "of value: useful\nfrom time to time: occasionally"}]$j$::jsonb),
  ('advanced', 'work-business', 'Hiệu quả của một cuộc họp nên được đo bằng quyết định và hành động tiếp theo, không phải thời lượng thảo luận.', $j$[{"text": "The effectiveness of a meeting should be measured by the decisions and follow-up actions, not the length of discussion.", "structureVi": "be measured by: được đo bằng\nnot + danh từ: chứ không phải", "structureEn": "be measured by: passive\nnot + noun: contrast"}, {"text": "A meeting's success ought to be judged on what it decides and what happens next, not on how long people talk.", "structureVi": "be judged on: được đánh giá dựa trên\nhow long + mệnh đề: bao lâu", "structureEn": "be judged on: evaluated by\nhow long + clause: duration"}]$j$::jsonb),
  ('advanced', 'public-services', 'Dịch vụ công chỉ thực sự thuận tiện khi quy trình số hóa không loại trừ người thiếu kỹ năng công nghệ.', $j$[{"text": "Public services are truly convenient only when digital procedures do not exclude people who lack technology skills.", "structureVi": "only when + mệnh đề: chỉ khi\npeople who + V: những người mà", "structureEn": "only when + clause: limiting condition\npeople who + V: relative clause"}, {"text": "Government services are really easy to use only if going digital doesn't leave out people who aren't comfortable with technology.", "structureVi": "only if + mệnh đề: chỉ nếu\nleave out: bỏ sót", "structureEn": "only if + clause: sole condition\nleave out: exclude"}]$j$::jsonb),
  ('advanced', 'public-services', 'Việc công khai tiêu chí xử lý hồ sơ giúp giảm nghi ngờ và tạo điều kiện để người dân giám sát.', $j$[{"text": "Making the criteria for processing applications public reduces suspicion and lets citizens monitor the process.", "structureVi": "Making + vật + tính từ: làm cho\nlet + người + V: cho phép", "structureEn": "Making + thing + adjective: cause to be\nlet + person + V: allow"}, {"text": "Publishing the standards used to handle applications lessens doubt and allows people to keep watch.", "structureVi": "used to handle: rút gọn mệnh đề\nallow + người + to + V: cho phép", "structureEn": "used to handle: reduced relative clause\nallow + person + to + V: permit"}]$j$::jsonb),
  ('advanced', 'public-services', 'Một hệ thống phản hồi hiệu quả cần cho người gửi biết ý kiến của họ được tiếp nhận và giải quyết ra sao.', $j$[{"text": "An effective feedback system should let senders know how their comments are received and resolved.", "structureVi": "let + người + know: cho ai biết\nhow + mệnh đề: như thế nào", "structureEn": "let + person + know: inform\nhow + clause: indirect question"}, {"text": "A good complaints process tells people what happened to their input and how it was dealt with.", "structureVi": "tell + người + what + mệnh đề: cho ai biết\ndeal with: giải quyết", "structureEn": "tell + person + what + clause: inform\ndeal with: handle"}]$j$::jsonb),
  ('advanced', 'public-services', 'Khi nguồn lực hạn chế, cơ quan công quyền nên ưu tiên dịch vụ dựa trên mức độ cấp thiết và lợi ích cộng đồng.', $j$[{"text": "When resources are limited, public agencies should prioritize services according to urgency and benefit to the community.", "structureVi": "When + mệnh đề: khi\naccording to: dựa theo", "structureEn": "When + clause: time\naccording to: based on"}, {"text": "With scarce resources, government bodies ought to put first the services that are most urgent and most beneficial to the public.", "structureVi": "With + danh từ: với\nthe services that + V: mệnh đề quan hệ", "structureEn": "With + noun: given\nthe services that + V: relative clause"}]$j$::jsonb),
  ('advanced', 'public-services', 'Thiết kế đô thị bao trùm đòi hỏi xem xét nhu cầu của người cao tuổi, trẻ em và người khuyết tật.', $j$[{"text": "Inclusive urban design requires considering the needs of older people, children and people with disabilities.", "structureVi": "require + V-ing: đòi hỏi\nthe needs of: nhu cầu của", "structureEn": "require + V-ing: need\nthe needs of: requirements of"}, {"text": "Designing cities for everyone means thinking about the elderly, young children and disabled residents.", "structureVi": "mean + V-ing: có nghĩa là\nthink about: nghĩ đến", "structureEn": "mean + V-ing: involve\nthink about: consider"}]$j$::jsonb),
  ('advanced', 'public-services', 'Cải cách thủ tục sẽ khó đạt kết quả nếu các đơn vị liên quan vẫn sử dụng quy trình và dữ liệu không tương thích.', $j$[{"text": "Procedural reform will struggle to succeed if the agencies involved still use incompatible processes and data.", "structureVi": "struggle to + V: khó\nthe agencies involved: các đơn vị liên quan", "structureEn": "struggle to + V: have difficulty\nthe agencies involved: reduced relative clause"}, {"text": "Simplifying administrative procedures is unlikely to work while the offices concerned keep using systems and data that don't fit together.", "structureVi": "be unlikely to + V: khó có thể\nwhile + mệnh đề: trong khi", "structureEn": "be unlikely to + V: improbable\nwhile + clause: at the same time"}]$j$::jsonb),
  ('advanced', 'public-services', 'Minh bạch không chỉ là công bố thông tin mà còn là trình bày thông tin theo cách công chúng có thể hiểu.', $j$[{"text": "Transparency is not only publishing information but also presenting it in a way the public can understand.", "structureVi": "not only A but also B: không chỉ A mà còn B\nin a way (that): theo cách", "structureEn": "not only A but also B: both\nin a way (that): manner"}, {"text": "Being transparent means more than releasing information; it means explaining it so that ordinary people can follow.", "structureVi": "more than: nhiều hơn\nso that + mệnh đề: để mà", "structureEn": "more than: beyond\nso that + clause: purpose"}]$j$::jsonb),
  ('advanced', 'public-services', 'Đầu tư vào bảo trì cơ sở hạ tầng thường ít gây chú ý hơn xây mới nhưng có thể tiết kiệm chi phí lâu dài.', $j$[{"text": "Investing in infrastructure maintenance is often less noticeable than building new facilities but can save money in the long run.", "structureVi": "less + tính từ + than: kém... hơn\nin the long run: về lâu dài", "structureEn": "less + adjective + than: comparison\nin the long run: over time"}, {"text": "Maintaining existing infrastructure attracts less attention than new construction, yet it may cut costs over time.", "structureVi": "attract attention: thu hút sự chú ý\nyet: nhưng", "structureEn": "attract attention: get noticed\nyet: however"}]$j$::jsonb),
  ('advanced', 'public-services', 'Niềm tin của người dân tăng lên khi quyết định hành chính được giải thích nhất quán và có thể kiểm chứng.', $j$[{"text": "Public trust grows when administrative decisions are explained consistently and can be verified.", "structureVi": "when + mệnh đề: khi\ncan be + V3: có thể được", "structureEn": "when + clause: time\ncan be + V3: passive possibility"}, {"text": "People trust the authorities more if their decisions are explained in a consistent way that can be checked.", "structureVi": "more + trạng từ: hơn\nthat can be checked: mệnh đề quan hệ", "structureEn": "more + adverb: comparative\nthat can be checked: relative clause"}]$j$::jsonb),
  ('advanced', 'public-services', 'Đánh giá chất lượng dịch vụ công nên kết hợp số liệu vận hành với trải nghiệm thực tế của người sử dụng.', $j$[{"text": "Evaluating the quality of public services should combine operational figures with users' real experiences.", "structureVi": "V-ing làm chủ ngữ: đánh giá\ncombine A with B: kết hợp", "structureEn": "V-ing as subject: evaluating\ncombine A with B: mix"}, {"text": "To judge how good a public service is, we need to look at both performance statistics and what users actually go through.", "structureVi": "To + V: để\nboth A and B: cả A lẫn B", "structureEn": "To + V: purpose\nboth A and B: two things"}]$j$::jsonb),
  ('advanced', 'health-medicine', 'Thông tin sức khỏe trên mạng cần được đánh giá dựa trên chất lượng bằng chứng chứ không phải mức độ lan truyền.', $j$[{"text": "Health information online should be evaluated on the quality of the evidence, not on how widely it spreads.", "structureVi": "be evaluated on: được đánh giá dựa trên\nhow widely: mức độ lan rộng", "structureEn": "be evaluated on: judged by\nhow widely: degree"}, {"text": "We ought to judge online health claims by how good the evidence is rather than by how viral they are.", "structureVi": "judge A by B: đánh giá A theo B\nrather than: hơn là", "structureEn": "judge A by B: assess\nrather than: instead of"}]$j$::jsonb),
  ('advanced', 'health-medicine', 'Một kế hoạch chăm sóc hiệu quả phải phù hợp với hoàn cảnh, khả năng tuân thủ và ưu tiên của từng người.', $j$[{"text": "An effective care plan must fit each person's circumstances, ability to follow it and priorities.", "structureVi": "fit + danh từ: phù hợp với\nability to + V: khả năng", "structureEn": "fit + noun: suit\nability to + V: capacity"}, {"text": "A good treatment plan has to suit the individual's situation, how well they can stick to it, and what matters most to them.", "structureVi": "suit: phù hợp\nwhat matters most to them: điều quan trọng nhất", "structureEn": "suit: be right for\nwhat matters most: noun clause"}]$j$::jsonb),
  ('advanced', 'health-medicine', 'Phòng bệnh ở cấp cộng đồng đòi hỏi phối hợp giữa giáo dục, môi trường sống và khả năng tiếp cận dịch vụ y tế.', $j$[{"text": "Disease prevention at the community level requires coordination between education, living environments and access to health services.", "structureVi": "require + danh từ: đòi hỏi\ncoordination between: sự phối hợp giữa", "structureEn": "require + noun: need\ncoordination between: working together"}, {"text": "Preventing illness in a community takes education, a healthy environment and access to care working together.", "structureVi": "take + danh từ: cần đến\nV-ing làm chủ ngữ: phòng bệnh", "structureEn": "take + noun: need\nV-ing as subject: preventing"}]$j$::jsonb),
  ('advanced', 'health-medicine', 'Việc giải thích rủi ro bằng ngôn ngữ dễ hiểu giúp bệnh nhân tham gia chủ động hơn vào quyết định điều trị.', $j$[{"text": "Explaining risks in plain language helps patients take a more active part in treatment decisions.", "structureVi": "V-ing làm chủ ngữ: giải thích\ntake part in: tham gia", "structureEn": "V-ing as subject: explaining\ntake part in: participate in"}, {"text": "When risks are described in simple words, patients can get more involved in deciding on their treatment.", "structureVi": "get involved in: tham gia vào\ndecide on: quyết định", "structureEn": "get involved in: participate\ndecide on: choose"}]$j$::jsonb),
  ('advanced', 'health-medicine', 'Không nên xem một kết quả nghiên cứu riêng lẻ là kết luận cuối cùng khi bằng chứng khoa học vẫn đang phát triển.', $j$[{"text": "A single research result should not be regarded as the final conclusion while the scientific evidence is still developing.", "structureVi": "should not be + V3: không nên được\nwhile + mệnh đề: trong khi", "structureEn": "should not be + V3: passive advice\nwhile + clause: at the same time"}, {"text": "One study shouldn't be treated as the last word when scientific evidence is still evolving.", "structureVi": "be treated as: được coi là\nstill + V-ing: vẫn đang", "structureEn": "be treated as: considered\nstill + V-ing: continuing"}]$j$::jsonb),
  ('advanced', 'health-medicine', 'Sức khỏe tinh thần chịu ảnh hưởng từ điều kiện xã hội nên không thể chỉ được giải quyết bằng nỗ lực cá nhân.', $j$[{"text": "Mental health is shaped by social conditions, so it cannot be addressed through individual effort alone.", "structureVi": "be shaped by: bị định hình bởi\nso + mệnh đề: vì vậy", "structureEn": "be shaped by: influenced by\nso + clause: result"}, {"text": "Because social circumstances influence mental well-being, personal effort on its own is not enough to solve it.", "structureVi": "Because + mệnh đề: vì\non its own: một mình", "structureEn": "Because + clause: reason\non its own: by itself"}]$j$::jsonb),
  ('advanced', 'health-medicine', 'Các chương trình can thiệp cần được đánh giá định kỳ để xác định liệu lợi ích có vượt quá chi phí hay không.', $j$[{"text": "Intervention programs need to be reviewed regularly to determine whether the benefits outweigh the costs.", "structureVi": "need to be + V3: cần được\nwhether + mệnh đề: liệu có", "structureEn": "need to be + V3: passive necessity\nwhether + clause: indirect question"}, {"text": "Health programs should be assessed from time to time to see if their advantages are greater than their costs.", "structureVi": "should be + V3: nên được\nsee if + mệnh đề: xem liệu", "structureEn": "should be + V3: passive advice\nsee if + clause: check whether"}]$j$::jsonb),
  ('advanced', 'health-medicine', 'Khuyến nghị y tế cần phân biệt rõ giữa mối liên hệ thống kê và quan hệ nhân quả.', $j$[{"text": "Medical recommendations need to distinguish clearly between a statistical association and a causal relationship.", "structureVi": "distinguish between A and B: phân biệt\nneed to + V: cần", "structureEn": "distinguish between A and B: tell apart\nneed to + V: necessity"}, {"text": "Health advice must make clear the difference between things that merely occur together and things that cause each other.", "structureVi": "make clear: làm rõ\nthe difference between: sự khác nhau", "structureEn": "make clear: clarify\nthe difference between: contrast"}]$j$::jsonb),
  ('advanced', 'health-medicine', 'Chính sách chăm sóc dự phòng có thể giảm áp lực cho bệnh viện nếu người dân tiếp cận được từ sớm.', $j$[{"text": "Preventive care policies can ease pressure on hospitals if people can access them early.", "structureVi": "ease pressure on: giảm áp lực\nif + mệnh đề: nếu", "structureEn": "ease pressure on: reduce strain\nif + clause: condition"}, {"text": "Policies on preventive care may relieve the burden on hospitals provided people get to use them at an early stage.", "structureVi": "relieve the burden on: giảm gánh nặng\nprovided (that): miễn là", "structureEn": "relieve the burden on: lighten\nprovided (that): condition"}]$j$::jsonb),
  ('advanced', 'health-medicine', 'Giao tiếp đồng cảm giúp nhân viên y tế hiểu mối lo của bệnh nhân mà không làm giảm tính chính xác chuyên môn.', $j$[{"text": "Empathetic communication helps medical staff understand patients' worries without reducing professional accuracy.", "structureVi": "help + người + V: giúp ai\nwithout + V-ing: mà không", "structureEn": "help + person + V: assist\nwithout + V-ing: not doing"}, {"text": "Showing empathy lets healthcare workers grasp what concerns their patients while remaining medically precise.", "structureVi": "let + người + V: cho phép\nwhile + V-ing: trong khi", "structureEn": "let + person + V: allow\nwhile + V-ing: at the same time"}]$j$::jsonb),
  ('advanced', 'shopping-money', 'Quyết định mua sắm hợp lý cần tính đến tổng chi phí sở hữu chứ không chỉ giá niêm yết ban đầu.', $j$[{"text": "A sensible purchasing decision should take into account the total cost of ownership, not just the original listed price.", "structureVi": "take into account: tính đến\nnot just: không chỉ", "structureEn": "take into account: consider\nnot just: more than"}, {"text": "Buying wisely means looking at everything an item will cost you over time, not only the sticker price.", "structureVi": "mean + V-ing: có nghĩa là\neverything (that) + mệnh đề: mọi thứ", "structureEn": "mean + V-ing: involve\neverything (that) + clause: relative clause"}]$j$::jsonb),
  ('advanced', 'shopping-money', 'Các chương trình giảm giá có thể thúc đẩy tiêu dùng bốc đồng nếu khách hàng không xác định nhu cầu từ trước.', $j$[{"text": "Discount programs can encourage impulse spending if customers haven't worked out what they need beforehand.", "structureVi": "encourage + danh từ: thúc đẩy\nwork out: xác định", "structureEn": "encourage + noun: promote\nwork out: figure out"}, {"text": "Sales may lead people to buy on impulse unless they have decided in advance what they really need.", "structureVi": "lead + người + to + V: dẫn đến\nunless + mệnh đề: trừ khi", "structureEn": "lead + person + to + V: cause\nunless + clause: if not"}]$j$::jsonb),
  ('advanced', 'shopping-money', 'Một ngân sách thực tế nên dành khoản dự phòng cho những chi phí bất thường thay vì giả định mọi tháng đều giống nhau.', $j$[{"text": "A realistic budget should set aside a reserve for unusual expenses instead of assuming every month is the same.", "structureVi": "set aside: dành ra\ninstead of + V-ing: thay vì", "structureEn": "set aside: reserve\ninstead of + V-ing: rather than"}, {"text": "A practical budget includes an emergency fund for irregular costs rather than assuming each month will be identical.", "structureVi": "include: bao gồm\nrather than + V-ing: thay vì", "structureEn": "include: contain\nrather than + V-ing: instead of"}]$j$::jsonb),
  ('advanced', 'shopping-money', 'Đánh giá độ bền và khả năng sửa chữa có thể giúp người tiêu dùng giảm chi phí trong dài hạn.', $j$[{"text": "Evaluating durability and repairability can help consumers reduce costs in the long term.", "structureVi": "V-ing làm chủ ngữ: đánh giá\nhelp + người + V: giúp", "structureEn": "V-ing as subject: evaluating\nhelp + person + V: assist"}, {"text": "Checking how long a product lasts and whether it can be fixed may save shoppers money over time.", "structureVi": "how long + mệnh đề: bao lâu\nwhether + mệnh đề: liệu", "structureEn": "how long + clause: duration\nwhether + clause: indirect question"}]$j$::jsonb),
  ('advanced', 'shopping-money', 'Sự tiện lợi của thanh toán số cần đi kèm biện pháp bảo vệ người dùng trước gian lận và lạm dụng dữ liệu.', $j$[{"text": "The convenience of digital payments needs to come with measures that protect users from fraud and data misuse.", "structureVi": "come with: đi kèm\nprotect A from B: bảo vệ A khỏi B", "structureEn": "come with: accompany\nprotect A from B: guard"}, {"text": "Paying digitally is convenient, but users also need safeguards against fraud and the misuse of their data.", "structureVi": "safeguards against: biện pháp bảo vệ khỏi\nthe misuse of: sự lạm dụng", "structureEn": "safeguards against: protection from\nthe misuse of: improper use"}]$j$::jsonb),
  ('advanced', 'shopping-money', 'Người mua nên xem xét điều kiện hoàn trả trước khi đặt hàng từ những nhà bán lẻ chưa quen thuộc.', $j$[{"text": "Buyers should consider the return conditions before ordering from retailers they are not familiar with.", "structureVi": "consider + danh từ: xem xét\nretailers (that) they are not familiar with: mệnh đề quan hệ", "structureEn": "consider + noun: think about\nretailers (that)...: relative clause"}, {"text": "Before placing an order with an unfamiliar seller, customers ought to look at the returns policy.", "structureVi": "Before + V-ing: trước khi\nunfamiliar: không quen thuộc", "structureEn": "Before + V-ing: before + gerund\nunfamiliar: not known"}]$j$::jsonb),
  ('advanced', 'shopping-money', 'Quảng cáo cá nhân hóa khiến việc phân biệt nhu cầu thật với mong muốn do tiếp thị tạo ra trở nên khó hơn.', $j$[{"text": "Personalized ads make it harder to tell real needs from desires created by marketing.", "structureVi": "make it + tính từ + to + V: khiến việc... trở nên\ntell A from B: phân biệt", "structureEn": "make it + adjective + to + V: cause difficulty\ntell A from B: distinguish"}, {"text": "Targeted advertising makes it more difficult to separate what we truly need from what marketers make us want.", "structureVi": "separate A from B: tách\nwhat + mệnh đề: điều mà", "structureEn": "separate A from B: distinguish\nwhat + clause: noun clause"}]$j$::jsonb),
  ('advanced', 'shopping-money', 'Một quyết định đầu tư cá nhân cần phản ánh khả năng chấp nhận rủi ro và mục tiêu theo thời gian.', $j$[{"text": "A personal investment decision needs to reflect one's tolerance for risk and goals over time.", "structureVi": "reflect + danh từ: phản ánh\ntolerance for: khả năng chấp nhận", "structureEn": "reflect + noun: show\ntolerance for: ability to accept"}, {"text": "Investing for yourself should match how much risk you can accept and what you want to achieve in the long term.", "structureVi": "match: phù hợp với\nhow much + mệnh đề: mức độ", "structureEn": "match: fit\nhow much + clause: degree"}]$j$::jsonb),
  ('advanced', 'shopping-money', 'Minh bạch về phí phát sinh giúp khách hàng so sánh sản phẩm dựa trên chi phí thực tế.', $j$[{"text": "Transparency about additional fees allows customers to compare products on the basis of real costs.", "structureVi": "allow + người + to + V: cho phép\non the basis of: dựa trên", "structureEn": "allow + person + to + V: permit\non the basis of: according to"}, {"text": "When extra charges are clearly stated, shoppers can compare products by what they actually cost.", "structureVi": "When + mệnh đề: khi\nby what + mệnh đề: dựa trên điều", "structureEn": "When + clause: condition\nby what + clause: noun clause"}]$j$::jsonb),
  ('advanced', 'shopping-money', 'Tiết kiệm bền vững thường bắt đầu từ việc hiểu dòng tiền thay vì cắt giảm mọi khoản chi một cách máy móc.', $j$[{"text": "Sustainable saving usually starts with understanding cash flow rather than mechanically cutting every expense.", "structureVi": "start with + V-ing: bắt đầu bằng\nrather than + V-ing: thay vì", "structureEn": "start with + V-ing: begin by\nrather than + V-ing: instead of"}, {"text": "Lasting savings habits typically begin by knowing where money comes and goes instead of slashing all spending automatically.", "structureVi": "begin by + V-ing: bắt đầu bằng\ninstead of + V-ing: thay vì", "structureEn": "begin by + V-ing: start with\ninstead of + V-ing: rather than"}]$j$::jsonb),
  ('advanced', 'food-drink', 'Việc bảo tồn món ăn truyền thống cần thích nghi với điều kiện hiện đại mà không làm mất đi ý nghĩa văn hóa.', $j$[{"text": "Preserving traditional dishes needs to adapt to modern conditions without losing their cultural meaning.", "structureVi": "need to + V: cần\nwithout + V-ing: mà không", "structureEn": "need to + V: necessity\nwithout + V-ing: not doing"}, {"text": "Keeping traditional food alive means adjusting to today's world while retaining its cultural significance.", "structureVi": "mean + V-ing: có nghĩa là\nwhile + V-ing: trong khi", "structureEn": "mean + V-ing: involve\nwhile + V-ing: at the same time"}]$j$::jsonb),
  ('advanced', 'food-drink', 'Một thực đơn cân bằng không nhất thiết loại bỏ hoàn toàn món yêu thích mà chú trọng khẩu phần và sự đa dạng.', $j$[{"text": "A balanced menu doesn't necessarily eliminate favorite dishes entirely but focuses on portions and variety.", "structureVi": "not necessarily: không nhất thiết\nfocus on: chú trọng", "structureEn": "not necessarily: not required\nfocus on: pay attention to"}, {"text": "Eating a balanced diet doesn't have to mean giving up the foods you love; what counts is portion size and variety.", "structureVi": "not have to + V: không cần\nwhat counts: điều quan trọng", "structureEn": "not have to + V: not necessary\nwhat counts: what matters"}]$j$::jsonb),
  ('advanced', 'food-drink', 'Nguồn gốc nguyên liệu ngày càng ảnh hưởng đến quyết định của thực khách quan tâm đến môi trường.', $j$[{"text": "The origin of ingredients increasingly affects the decisions of diners who care about the environment.", "structureVi": "increasingly + V: ngày càng\ndiners who + V: mệnh đề quan hệ", "structureEn": "increasingly + V: more and more\ndiners who + V: relative clause"}, {"text": "Where ingredients come from matters more and more to customers who are concerned about the environment.", "structureVi": "Where + mệnh đề: nơi mà (chủ ngữ)\nmore and more: ngày càng", "structureEn": "Where + clause: noun clause subject\nmore and more: increasingly"}]$j$::jsonb),
  ('advanced', 'food-drink', 'Nhà hàng có thể giảm lãng phí thực phẩm bằng cách dự báo nhu cầu chính xác và điều chỉnh khẩu phần.', $j$[{"text": "Restaurants can reduce food waste by forecasting demand accurately and adjusting portion sizes.", "structureVi": "by + V-ing: bằng cách\nreduce + danh từ: giảm", "structureEn": "by + V-ing: method\nreduce + noun: cut down"}, {"text": "Restaurants are able to waste less food if they predict demand precisely and change their portions.", "structureVi": "waste less: lãng phí ít hơn\nif + mệnh đề: nếu", "structureEn": "waste less: comparative\nif + clause: condition"}]$j$::jsonb),
  ('advanced', 'food-drink', 'Sự phổ biến toàn cầu của một món ăn đôi khi khiến phiên bản địa phương bị đơn giản hóa để phù hợp thị hiếu.', $j$[{"text": "The global popularity of a dish sometimes causes local versions to be simplified to suit tastes.", "structureVi": "cause + vật + to be + V3: khiến\nto suit: để phù hợp", "structureEn": "cause + thing + to be + V3: passive result\nto suit: purpose"}, {"text": "When a dish becomes popular worldwide, its local versions are sometimes made simpler to please more people.", "structureVi": "When + mệnh đề: khi\nare made + tính từ: được làm cho", "structureEn": "When + clause: time\nare made + adjective: passive"}]$j$::jsonb),
  ('advanced', 'food-drink', 'Kỹ thuật chế biến không chỉ thay đổi hương vị mà còn ảnh hưởng đến kết cấu và giá trị dinh dưỡng.', $j$[{"text": "Cooking techniques not only change flavor but also affect texture and nutritional value.", "structureVi": "not only A but also B: không chỉ A mà còn B\naffect + danh từ: ảnh hưởng", "structureEn": "not only A but also B: both\naffect + noun: influence"}, {"text": "The way food is prepared alters its taste as well as its texture and nutritional content.", "structureVi": "the way + mệnh đề: cách mà\nA as well as B: cả A lẫn B", "structureEn": "the way + clause: manner\nA as well as B: and also"}]$j$::jsonb),
  ('advanced', 'food-drink', 'Đánh giá một nền ẩm thực qua vài món nổi tiếng dễ bỏ qua sự đa dạng giữa các vùng và cộng đồng.', $j$[{"text": "Judging a cuisine by a few famous dishes easily overlooks the diversity between regions and communities.", "structureVi": "Judging: V-ing làm chủ ngữ\noverlook + danh từ: bỏ qua", "structureEn": "Judging: gerund subject\noverlook + noun: fail to notice"}, {"text": "If you assess a food culture only through a handful of well-known dishes, you tend to miss its variety across regions and groups.", "structureVi": "only through: chỉ qua\ntend to + V: dễ", "structureEn": "only through: limiting\ntend to + V: be likely to"}]$j$::jsonb),
  ('advanced', 'food-drink', 'Việc ghi nhãn dị ứng rõ ràng giúp thực khách lựa chọn an toàn hơn khi dùng bữa ngoài nhà.', $j$[{"text": "Clear allergy labeling helps diners make safer choices when eating out.", "structureVi": "help + người + V: giúp\nmake choices: lựa chọn", "structureEn": "help + person + V: assist\nmake choices: select"}, {"text": "Allergen information that is clearly shown lets people choose more safely when they dine out.", "structureVi": "information that is shown: mệnh đề quan hệ\ndine out: ăn ngoài", "structureEn": "information that is shown: relative clause\ndine out: eat at restaurants"}]$j$::jsonb),
  ('advanced', 'food-drink', 'Nông nghiệp theo mùa có thể giảm áp lực vận chuyển nếu chuỗi cung ứng được tổ chức phù hợp.', $j$[{"text": "Seasonal farming can reduce transport pressure if the supply chain is organized appropriately.", "structureVi": "can + V: có thể\nif + mệnh đề: nếu", "structureEn": "can + V: possibility\nif + clause: condition"}, {"text": "Growing food in season may ease the strain on transport provided supply chains are set up suitably.", "structureVi": "ease the strain on: giảm áp lực\nprovided (that): miễn là", "structureEn": "ease the strain on: reduce pressure\nprovided (that): condition"}]$j$::jsonb),
  ('advanced', 'food-drink', 'Chia sẻ bữa ăn tạo cơ hội kết nối xã hội, nhưng thói quen ăn uống vẫn khác nhau theo hoàn cảnh cá nhân.', $j$[{"text": "Sharing meals creates opportunities for social connection, but eating habits still differ according to personal circumstances.", "structureVi": "create opportunities for: tạo cơ hội\ndiffer according to: khác nhau tùy theo", "structureEn": "create opportunities for: give chances\ndiffer according to: vary depending on"}, {"text": "Eating together lets people bond, although what each person eats still depends on their own situation.", "structureVi": "let + người + V: cho phép\nalthough + mệnh đề: mặc dù", "structureEn": "let + person + V: allow\nalthough + clause: contrast"}]$j$::jsonb),
  ('advanced', 'entertainment-leisure', 'Giải trí có giá trị không chỉ vì giúp thư giãn mà còn vì mở rộng góc nhìn về trải nghiệm con người.', $j$[{"text": "Entertainment is valuable not only because it helps us relax but also because it broadens our view of human experience.", "structureVi": "not only because A but also because B: không chỉ vì\nbroaden: mở rộng", "structureEn": "not only because A but also because B: two reasons\nbroaden: widen"}, {"text": "Entertainment matters both as a way to unwind and as a way of understanding what it means to be human.", "structureVi": "both as A and as B: vừa là A vừa là B\nwhat it means to + V: ý nghĩa của việc", "structureEn": "both as A and as B: two roles\nwhat it means to + V: noun clause"}]$j$::jsonb),
  ('advanced', 'entertainment-leisure', 'Nền tảng phát trực tuyến tạo nhiều lựa chọn hơn nhưng thuật toán đề xuất có thể thu hẹp sự đa dạng nội dung.', $j$[{"text": "Streaming platforms offer more choices, but recommendation algorithms may narrow content diversity.", "structureVi": "more + danh từ: nhiều hơn\nmay + V: có thể", "structureEn": "more + noun: greater amount\nmay + V: possibility"}, {"text": "Although streaming services give viewers more options, their suggestion algorithms can reduce the variety of what people watch.", "structureVi": "Although + mệnh đề: mặc dù\nthe variety of: sự đa dạng", "structureEn": "Although + clause: contrast\nthe variety of: diversity"}]$j$::jsonb),
  ('advanced', 'entertainment-leisure', 'Một lễ hội thành công cần cân bằng trải nghiệm của khách tham dự với đời sống thường ngày của cư dân địa phương.', $j$[{"text": "A successful festival needs to balance the experience of attendees with the everyday lives of local residents.", "structureVi": "balance A with B: cân bằng A với B\nthe everyday lives of: đời sống thường ngày", "structureEn": "balance A with B: weigh together\nthe everyday lives of: normal life"}, {"text": "To be successful, a festival has to strike a balance between what visitors enjoy and the daily routine of the people who live nearby.", "structureVi": "strike a balance between: cân bằng\nthe people who + V: những người", "structureEn": "strike a balance between: balance\nthe people who + V: relative clause"}]$j$::jsonb),
  ('advanced', 'entertainment-leisure', 'Việc biến sở thích thành công việc có thể đem lại thu nhập nhưng cũng làm thay đổi cảm giác tự do ban đầu.', $j$[{"text": "Turning a hobby into a job can bring income but may also change the original sense of freedom.", "structureVi": "turn A into B: biến A thành B\nmay also + V: cũng có thể", "structureEn": "turn A into B: convert\nmay also + V: also possible"}, {"text": "Making a living from a pastime can pay the bills, yet it may alter the freedom you first felt.", "structureVi": "make a living from: kiếm sống bằng\nthe freedom (that) you first felt: mệnh đề quan hệ", "structureEn": "make a living from: earn money\nthe freedom (that)...: relative clause"}]$j$::jsonb),
  ('advanced', 'entertainment-leisure', 'Các tác phẩm gây tranh luận thường buộc khán giả phân biệt giữa ý định của nghệ sĩ và cách công chúng diễn giải.', $j$[{"text": "Controversial works often force audiences to distinguish between the artist's intention and how the public interprets it.", "structureVi": "force + người + to + V: buộc ai\ndistinguish between A and B: phân biệt", "structureEn": "force + person + to + V: compel\ndistinguish between A and B: tell apart"}, {"text": "Provocative artworks frequently make viewers separate what the artist meant from the way people read them.", "structureVi": "make + người + V: khiến\nwhat + mệnh đề: điều mà", "structureEn": "make + person + V: cause\nwhat + clause: noun clause"}]$j$::jsonb),
  ('advanced', 'entertainment-leisure', 'Không gian công cộng dành cho hoạt động văn hóa giúp những nhóm ít có cơ hội tiếp cận nghệ thuật tham gia nhiều hơn.', $j$[{"text": "Public spaces for cultural activities help groups with fewer opportunities to access art participate more.", "structureVi": "help + người + V: giúp\ngroups with + danh từ: nhóm có", "structureEn": "help + person + V: assist\ngroups with + noun: groups having"}, {"text": "Community venues for the arts make it easier for people with little access to art to take part.", "structureVi": "make it easier for + người + to + V: giúp dễ dàng hơn\ntake part: tham gia", "structureEn": "make it easier for + person + to + V: facilitate\ntake part: participate"}]$j$::jsonb),
  ('advanced', 'entertainment-leisure', 'Sự nổi tiếng trên mạng không nhất thiết phản ánh chiều sâu nghệ thuật hay ảnh hưởng lâu dài của một tác phẩm.', $j$[{"text": "Popularity online does not necessarily reflect artistic depth or the lasting influence of a work.", "structureVi": "not necessarily: không nhất thiết\nthe lasting influence of: ảnh hưởng lâu dài", "structureEn": "not necessarily: not always\nthe lasting influence of: long-term effect"}, {"text": "Being famous on the internet doesn't always mean a work has depth or will have a long-term impact.", "structureVi": "Being + tính từ: việc nổi tiếng\ndoesn't always mean: không phải lúc nào cũng", "structureEn": "Being + adjective: gerund subject\ndoesn't always mean: partial negation"}]$j$::jsonb),
  ('advanced', 'entertainment-leisure', 'Một hoạt động giải trí có ý nghĩa hơn khi người tham gia cảm thấy được kết nối thay vì chỉ tiêu thụ nội dung.', $j$[{"text": "A leisure activity is more meaningful when participants feel connected rather than just consuming content.", "structureVi": "more + tính từ: hơn\nrather than + V-ing: thay vì", "structureEn": "more + adjective: comparative\nrather than + V-ing: instead of"}, {"text": "A pastime means more to us if we feel a sense of connection instead of simply taking in content.", "structureVi": "mean more to: có ý nghĩa hơn với\ninstead of + V-ing: thay vì", "structureEn": "mean more to: be more valuable\ninstead of + V-ing: rather than"}]$j$::jsonb),
  ('advanced', 'entertainment-leisure', 'Bảo vệ quyền sáng tạo cần đi đôi với việc đảm bảo công chúng có thể tiếp cận văn hóa một cách hợp lý.', $j$[{"text": "Protecting creative rights must go together with ensuring that the public can reasonably access culture.", "structureVi": "go together with: đi đôi với\nensure that: bảo đảm rằng", "structureEn": "go together with: accompany\nensure that: make certain"}, {"text": "Safeguarding creators' rights has to be accompanied by fair public access to cultural works.", "structureVi": "be accompanied by: đi kèm với\nfair access to: tiếp cận hợp lý", "structureEn": "be accompanied by: go with\nfair access to: reasonable use"}]$j$::jsonb),
  ('advanced', 'entertainment-leisure', 'Dành thời gian không có lịch trình đôi khi giúp nảy sinh ý tưởng mà công việc có cấu trúc khó tạo ra.', $j$[{"text": "Spending time without a schedule sometimes helps generate ideas that structured work struggles to produce.", "structureVi": "spend time + V-ing: dành thời gian\nideas that + V: ý tưởng mà", "structureEn": "spend time + V-ing: use time\nideas that + V: relative clause"}, {"text": "Unplanned time can give rise to ideas that a rigid work routine rarely creates.", "structureVi": "give rise to: làm nảy sinh\nrarely + V: hiếm khi", "structureEn": "give rise to: produce\nrarely + V: seldom"}]$j$::jsonb),
  ('advanced', 'nature-environment', 'Chính sách bảo tồn chỉ bền vững khi cộng đồng địa phương được tham gia và hưởng lợi từ việc bảo vệ hệ sinh thái.', $j$[{"text": "Conservation policies are sustainable only when local communities take part in and benefit from protecting the ecosystem.", "structureVi": "only when + mệnh đề: chỉ khi\ntake part in and benefit from: tham gia và hưởng lợi", "structureEn": "only when + clause: limiting condition\ntake part in and benefit from: two verbs sharing an object"}, {"text": "Protection policies last only if local people are involved in safeguarding the ecosystem and gain from it.", "structureVi": "be involved in: tham gia\ngain from: hưởng lợi từ", "structureEn": "be involved in: participate\ngain from: profit from"}]$j$::jsonb),
  ('advanced', 'nature-environment', 'Giảm phát thải cần phối hợp thay đổi hành vi cá nhân với đầu tư hạ tầng và quy định ở quy mô lớn.', $j$[{"text": "Reducing emissions requires combining individual behavior change with infrastructure investment and large-scale regulation.", "structureVi": "require + V-ing: đòi hỏi\ncombine A with B: kết hợp", "structureEn": "require + V-ing: need\ncombine A with B: mix"}, {"text": "Cutting emissions needs personal habits to change alongside investment in infrastructure and broad regulations.", "structureVi": "need + danh từ + to + V: cần\nalongside: song song với", "structureEn": "need + noun + to + V: require\nalongside: together with"}]$j$::jsonb),
  ('advanced', 'nature-environment', 'Một khu vực xanh có thể cải thiện chất lượng sống nhưng cần được phân bố công bằng giữa các khu dân cư.', $j$[{"text": "A green area can improve quality of life but needs to be fairly distributed among residential areas.", "structureVi": "can + V: có thể\nbe distributed among: được phân bổ giữa", "structureEn": "can + V: ability\nbe distributed among: shared across"}, {"text": "Green spaces make life better, yet they should be shared out evenly between neighborhoods.", "structureVi": "make + vật + tính từ: khiến\nbe shared out: được chia", "structureEn": "make + thing + adjective: cause\nbe shared out: distributed"}]$j$::jsonb),
  ('advanced', 'nature-environment', 'Đánh giá tác động môi trường nên tính đến hậu quả tích lũy thay vì chỉ xem xét từng dự án riêng lẻ.', $j$[{"text": "Environmental impact assessments should consider cumulative consequences rather than looking at each project separately.", "structureVi": "should + V: nên\nrather than + V-ing: thay vì", "structureEn": "should + V: advice\nrather than + V-ing: instead of"}, {"text": "Assessing environmental impact ought to take the combined effects into account instead of examining each project on its own.", "structureVi": "Assessing: V-ing làm chủ ngữ\ntake into account: tính đến", "structureEn": "Assessing: gerund subject\ntake into account: consider"}]$j$::jsonb),
  ('advanced', 'nature-environment', 'Việc phục hồi sinh cảnh đòi hỏi hiểu mối liên hệ giữa các loài thay vì chỉ trồng thêm cây một cách đại trà.', $j$[{"text": "Restoring habitats requires understanding the relationships among species rather than simply planting more trees on a large scale.", "structureVi": "require + V-ing: đòi hỏi\nrather than simply + V-ing: thay vì chỉ", "structureEn": "require + V-ing: need\nrather than simply + V-ing: not only"}, {"text": "Bringing a habitat back means knowing how species depend on one another, not just planting trees everywhere.", "structureVi": "bring back: khôi phục\nhow + mệnh đề: cách mà", "structureEn": "bring back: restore\nhow + clause: manner"}]$j$::jsonb),
  ('advanced', 'nature-environment', 'Các giải pháp tái chế khó đạt hiệu quả nếu sản phẩm ngay từ đầu được thiết kế để khó tháo rời.', $j$[{"text": "Recycling solutions are hard to make effective if products are designed from the start to be difficult to take apart.", "structureVi": "be hard to + V: khó\ndesigned to be + tính từ: được thiết kế để", "structureEn": "be hard to + V: difficult\ndesigned to be + adjective: passive purpose"}, {"text": "Recycling can hardly work well when goods are made in a way that makes them difficult to dismantle.", "structureVi": "hardly + V: khó mà\nin a way that: theo cách", "structureEn": "hardly + V: almost not\nin a way that: manner"}]$j$::jsonb),
  ('advanced', 'nature-environment', 'Thích ứng với biến đổi khí hậu cần ưu tiên nhóm dân cư dễ bị tổn thương trước các hiện tượng thời tiết cực đoan.', $j$[{"text": "Adapting to climate change must prioritize groups of residents who are vulnerable to extreme weather.", "structureVi": "must + V: phải\ngroups who are vulnerable to: nhóm dễ bị tổn thương", "structureEn": "must + V: obligation\ngroups who are vulnerable to: relative clause"}, {"text": "Climate adaptation should give priority to the communities that are most exposed to severe weather events.", "structureVi": "give priority to: ưu tiên\nexposed to: chịu ảnh hưởng của", "structureEn": "give priority to: put first\nexposed to: at risk from"}]$j$::jsonb),
  ('advanced', 'nature-environment', 'Tăng trưởng kinh tế và bảo vệ thiên nhiên không nhất thiết đối lập nếu chi phí môi trường được phản ánh đầy đủ.', $j$[{"text": "Economic growth and nature protection are not necessarily opposed if environmental costs are fully reflected.", "structureVi": "not necessarily: không nhất thiết\nif + mệnh đề: nếu", "structureEn": "not necessarily: not always\nif + clause: condition"}, {"text": "Growing the economy and protecting nature needn't conflict provided the full environmental cost is accounted for.", "structureVi": "needn't + V: không cần\nprovided (that): miễn là", "structureEn": "needn't + V: not necessary\nprovided (that): condition"}]$j$::jsonb),
  ('advanced', 'nature-environment', 'Dữ liệu quan trắc dài hạn giúp phân biệt biến động tự nhiên với xu hướng thay đổi của hệ sinh thái.', $j$[{"text": "Long-term monitoring data help distinguish natural fluctuations from trends of change in an ecosystem.", "structureVi": "help + V: giúp\ndistinguish A from B: phân biệt", "structureEn": "help + V: assist\ndistinguish A from B: tell apart"}, {"text": "Data collected over many years make it possible to tell natural ups and downs from lasting changes in an ecosystem.", "structureVi": "data collected: rút gọn mệnh đề quan hệ\nmake it possible to + V: giúp có thể", "structureEn": "data collected: reduced relative clause\nmake it possible to + V: enable"}]$j$::jsonb),
  ('advanced', 'nature-environment', 'Bảo vệ tài nguyên chung đòi hỏi cơ chế quản lý đủ minh bạch để ngăn lợi ích ngắn hạn lấn át lợi ích lâu dài.', $j$[{"text": "Protecting shared resources requires management mechanisms transparent enough to prevent short-term interests from overriding long-term ones.", "structureVi": "enough to + V: đủ để\nprevent A from + V-ing: ngăn A", "structureEn": "enough to + V: sufficient\nprevent A from + V-ing: stop"}, {"text": "Looking after common resources calls for open governance that stops short-term gain from outweighing long-term benefits.", "structureVi": "call for: đòi hỏi\nstop A from + V-ing: ngăn A", "structureEn": "call for: require\nstop A from + V-ing: prevent"}]$j$::jsonb),
  ('advanced', 'science-technology', 'Một hệ thống trí tuệ nhân tạo đáng tin cậy cần được đánh giá cả về độ chính xác lẫn tác động xã hội.', $j$[{"text": "A trustworthy artificial intelligence system should be evaluated for both its accuracy and its social impact.", "structureVi": "should be + V3: nên được\nboth A and B: cả A lẫn B", "structureEn": "should be + V3: passive advice\nboth A and B: two aspects"}, {"text": "We need to judge a reliable AI system not only by how accurate it is but also by what effect it has on society.", "structureVi": "not only A but also B: không chỉ A mà còn B\nwhat effect: tác động gì", "structureEn": "not only A but also B: both\nwhat effect: noun clause"}]$j$::jsonb),
  ('advanced', 'science-technology', 'Tự động hóa có thể nâng cao năng suất nhưng lợi ích phân phối không đồng đều nếu người lao động thiếu cơ hội đào tạo.', $j$[{"text": "Automation can raise productivity, but the benefits are unevenly distributed if workers lack training opportunities.", "structureVi": "can + V: có thể\nif + mệnh đề: nếu", "structureEn": "can + V: possibility\nif + clause: condition"}, {"text": "Automating work may boost output, yet its gains are shared unequally when employees have no chance to retrain.", "structureVi": "boost: tăng\nwhen + mệnh đề: khi", "structureEn": "boost: raise\nwhen + clause: condition"}]$j$::jsonb),
  ('advanced', 'science-technology', 'Quyền riêng tư nên được xem xét ngay từ giai đoạn thiết kế sản phẩm thay vì bổ sung sau khi xảy ra sự cố.', $j$[{"text": "Privacy should be considered from the product design stage rather than added after an incident occurs.", "structureVi": "should be + V3: nên được\nrather than + V3: thay vì", "structureEn": "should be + V3: passive advice\nrather than + V3: instead of"}, {"text": "Privacy ought to be built in at the design phase instead of being added once something goes wrong.", "structureVi": "be built in: được tích hợp\nonce + mệnh đề: một khi", "structureEn": "be built in: included from the start\nonce + clause: after"}]$j$::jsonb),
  ('advanced', 'science-technology', 'Kết quả mô hình dự đoán chỉ hữu ích khi người dùng hiểu giới hạn và nguồn gốc của dữ liệu đầu vào.', $j$[{"text": "Predictive model results are useful only when users understand the limitations and sources of the input data.", "structureVi": "only when + mệnh đề: chỉ khi\nthe limitations of: giới hạn của", "structureEn": "only when + clause: limiting condition\nthe limitations of: weaknesses"}, {"text": "A forecasting model helps only if people know where its data come from and what it cannot do.", "structureVi": "only if + mệnh đề: chỉ nếu\nwhere + mệnh đề: nguồn", "structureEn": "only if + clause: sole condition\nwhere + clause: noun clause"}]$j$::jsonb),
  ('advanced', 'science-technology', 'Tiến bộ công nghệ cần cơ chế giám sát đủ linh hoạt để theo kịp những rủi ro mới phát sinh.', $j$[{"text": "Technological progress needs oversight mechanisms flexible enough to keep up with newly emerging risks.", "structureVi": "flexible enough to + V: đủ linh hoạt để\nkeep up with: theo kịp", "structureEn": "flexible enough to + V: sufficiently\nkeep up with: stay level with"}, {"text": "Advances in technology call for supervision that can adapt quickly to risks as they appear.", "structureVi": "call for: đòi hỏi\nthat can adapt: mệnh đề quan hệ", "structureEn": "call for: require\nthat can adapt: relative clause"}]$j$::jsonb),
  ('advanced', 'science-technology', 'Một thuật toán có thể tái tạo định kiến sẵn có nếu dữ liệu huấn luyện không phản ánh đầy đủ các nhóm liên quan.', $j$[{"text": "An algorithm can reproduce existing biases if the training data doesn't fully reflect the groups involved.", "structureVi": "can + V: có thể\nif + mệnh đề: nếu", "structureEn": "can + V: possibility\nif + clause: condition"}, {"text": "Algorithms may repeat existing prejudices when the data used to train them fail to represent the relevant groups.", "structureVi": "when + mệnh đề: khi\nthe data used to train: rút gọn mệnh đề quan hệ", "structureEn": "when + clause: condition\nthe data used to train: reduced relative clause"}]$j$::jsonb),
  ('advanced', 'science-technology', 'Khả năng truy cập công nghệ phụ thuộc không chỉ vào thiết bị mà còn vào kỹ năng và thiết kế phù hợp.', $j$[{"text": "Access to technology depends not only on devices but also on skills and appropriate design.", "structureVi": "depend on: phụ thuộc vào\nnot only A but also B: không chỉ A mà còn B", "structureEn": "depend on: be determined by\nnot only A but also B: both"}, {"text": "Being able to use technology isn't just a matter of owning devices; it also takes skills and suitable design.", "structureVi": "a matter of: vấn đề của\ntake + danh từ: cần", "structureEn": "a matter of: question of\ntake + noun: require"}]$j$::jsonb),
  ('advanced', 'science-technology', 'Nghiên cứu khoa học đáng tin cậy cần công khai phương pháp để người khác có thể kiểm tra và tái lập kết quả.', $j$[{"text": "Reliable scientific research needs to publish its methods so that others can check and reproduce the results.", "structureVi": "need to + V: cần\nso that + mệnh đề: để mà", "structureEn": "need to + V: necessity\nso that + clause: purpose"}, {"text": "Credible science must make its methods public so other people are able to verify and replicate its findings.", "structureVi": "must + V: phải\nbe able to + V: có thể", "structureEn": "must + V: obligation\nbe able to + V: can"}]$j$::jsonb),
  ('advanced', 'science-technology', 'Sự tiện lợi của các dịch vụ kết nối cần được cân nhắc với mức độ phụ thuộc vào một nền tảng duy nhất.', $j$[{"text": "The convenience of connected services needs to be weighed against dependence on a single platform.", "structureVi": "be weighed against: được cân nhắc với\ndependence on: sự phụ thuộc vào", "structureEn": "be weighed against: compared with\ndependence on: reliance on"}, {"text": "We should balance how convenient connected services are against the risk of relying on just one platform.", "structureVi": "balance A against B: cân bằng\nthe risk of + V-ing: rủi ro", "structureEn": "balance A against B: weigh\nthe risk of + V-ing: danger of"}]$j$::jsonb),
  ('advanced', 'science-technology', 'Đổi mới có trách nhiệm đòi hỏi nhà phát triển dự đoán hậu quả ngoài mục tiêu sử dụng ban đầu.', $j$[{"text": "Responsible innovation requires developers to anticipate consequences beyond the original intended use.", "structureVi": "require + người + to + V: đòi hỏi ai\nbeyond + danh từ: vượt ngoài", "structureEn": "require + person + to + V: need someone to\nbeyond + noun: outside"}, {"text": "Innovating responsibly means developers must foresee effects that go past what a product was first meant for.", "structureVi": "mean + mệnh đề: có nghĩa là\neffects that + V: mệnh đề quan hệ", "structureEn": "mean + clause: involve\neffects that + V: relative clause"}]$j$::jsonb),
  ('advanced', 'culture-society', 'Bản sắc văn hóa không bất biến mà liên tục được thương lượng qua tiếp xúc và thay đổi xã hội.', $j$[{"text": "Cultural identity is not fixed but is continually negotiated through contact and social change.", "structureVi": "not A but B: không phải A mà là B\nbe negotiated: được thương lượng", "structureEn": "not A but B: contrast\nbe negotiated: passive"}, {"text": "Identity in a culture doesn't stay the same; it keeps being reshaped by interaction and a changing society.", "structureVi": "keep + being + V3: liên tục bị\nreshape: định hình lại", "structureEn": "keep + being + V3: continuous passive\nreshape: form again"}]$j$::jsonb),
  ('advanced', 'culture-society', 'Chính sách hòa nhập cần giải quyết rào cản cấu trúc thay vì chỉ kêu gọi thái độ tích cực từ cá nhân.', $j$[{"text": "Inclusion policies need to address structural barriers rather than only calling for positive attitudes from individuals.", "structureVi": "address + danh từ: giải quyết\nrather than + V-ing: thay vì", "structureEn": "address + noun: deal with\nrather than + V-ing: instead of"}, {"text": "Policies for inclusion must tackle systemic obstacles instead of merely asking individuals to be more accepting.", "structureVi": "tackle: giải quyết\ninstead of merely + V-ing: thay vì chỉ", "structureEn": "tackle: address\ninstead of merely + V-ing: not only"}]$j$::jsonb),
  ('advanced', 'culture-society', 'Sự khác biệt thế hệ thường phản ánh những điều kiện kinh tế và công nghệ mà mỗi nhóm đã trải qua.', $j$[{"text": "Generational differences often reflect the economic and technological conditions each group has experienced.", "structureVi": "reflect + danh từ: phản ánh\nconditions (that) each group has experienced: mệnh đề quan hệ", "structureEn": "reflect + noun: show\nconditions (that)...: relative clause"}, {"text": "Gaps between generations usually come from the economic and technological circumstances that each one has lived through.", "structureVi": "come from: bắt nguồn từ\nlive through: trải qua", "structureEn": "come from: result from\nlive through: experience"}]$j$::jsonb),
  ('advanced', 'culture-society', 'Bảo tồn di sản sống hiệu quả hơn khi cộng đồng thực hành văn hóa có quyền quyết định cách truyền tiếp.', $j$[{"text": "Preserving living heritage is more effective when the communities practicing the culture have a say in how it is passed on.", "structureVi": "more effective when: hiệu quả hơn khi\nhave a say in: có tiếng nói", "structureEn": "more effective when: comparison\nhave a say in: take part in deciding"}, {"text": "Living traditions are better protected if the people who practice them decide how they are handed down.", "structureVi": "be better protected: được bảo vệ tốt hơn\nhand down: truyền lại", "structureEn": "be better protected: comparative passive\nhand down: pass on"}]$j$::jsonb),
  ('advanced', 'culture-society', 'Mạng xã hội mở rộng cơ hội lên tiếng nhưng cũng có thể khuếch đại những quan điểm cực đoan.', $j$[{"text": "Social media expands opportunities to speak out but can also amplify extreme views.", "structureVi": "expand + danh từ: mở rộng\nbut can also + V: nhưng cũng có thể", "structureEn": "expand + noun: widen\nbut can also + V: contrast"}, {"text": "Social networks give more people a voice, though they may also boost radical opinions.", "structureVi": "give + người + vật: mang lại cho ai\nthough + mệnh đề: tuy nhiên", "structureEn": "give + person + thing: provide\nthough + clause: contrast"}]$j$::jsonb),
  ('advanced', 'culture-society', 'Một xã hội đa dạng cần không gian để bất đồng được thể hiện mà không biến thành sự loại trừ lẫn nhau.', $j$[{"text": "A diverse society needs room for disagreement to be expressed without turning into mutual exclusion.", "structureVi": "need + danh từ + to be + V3: cần\nwithout + V-ing: mà không", "structureEn": "need + noun + to be + V3: passive purpose\nwithout + V-ing: not doing"}, {"text": "In a varied society, people should be able to disagree openly without ending up excluding one another.", "structureVi": "be able to + V: có thể\nend up + V-ing: kết cục là", "structureEn": "be able to + V: can\nend up + V-ing: finally"}]$j$::jsonb),
  ('advanced', 'culture-society', 'Di cư làm thay đổi cộng đồng tiếp nhận đồng thời tạo ra những mạng lưới kết nối xuyên biên giới.', $j$[{"text": "Migration changes receiving communities while creating networks of connection across borders.", "structureVi": "change + danh từ: thay đổi\nwhile + V-ing: đồng thời", "structureEn": "change + noun: alter\nwhile + V-ing: at the same time"}, {"text": "People moving to new countries transform the communities that welcome them and, at the same time, build links that cross national lines.", "structureVi": "People + V-ing: những người đang\nat the same time: đồng thời", "structureEn": "People + V-ing: reduced relative clause\nat the same time: simultaneously"}]$j$::jsonb),
  ('advanced', 'culture-society', 'Các số liệu trung bình có thể che khuất bất bình đẳng nếu không được phân tích theo nhóm dân cư.', $j$[{"text": "Average figures can hide inequality if they aren't analyzed by population group.", "structureVi": "can + V: có thể\nif + mệnh đề: nếu", "structureEn": "can + V: possibility\nif + clause: condition"}, {"text": "Averages may conceal inequality unless the data is broken down by different groups of people.", "structureVi": "unless + mệnh đề: trừ khi\nbreak down by: phân tích theo", "structureEn": "unless + clause: if not\nbreak down by: split into categories"}]$j$::jsonb),
  ('advanced', 'culture-society', 'Sự tham gia tình nguyện bền vững cần cơ cấu hỗ trợ chứ không thể chỉ dựa vào thiện chí nhất thời.', $j$[{"text": "Sustainable volunteering needs support structures and cannot rely on temporary goodwill alone.", "structureVi": "need + danh từ: cần\nrely on: dựa vào", "structureEn": "need + noun: require\nrely on: depend on"}, {"text": "Volunteer work can only last if there are structures to support it, not just a passing wave of goodwill.", "structureVi": "can only + V: chỉ có thể\nnot just: không chỉ", "structureEn": "can only + V: limit\nnot just: more than"}]$j$::jsonb),
  ('advanced', 'culture-society', 'Đối thoại liên văn hóa có ý nghĩa khi các bên sẵn sàng xem xét cả quyền lực lẫn những giả định của mình.', $j$[{"text": "Intercultural dialogue is meaningful when the parties are willing to examine both power and their own assumptions.", "structureVi": "be willing to + V: sẵn sàng\nboth A and B: cả A lẫn B", "structureEn": "be willing to + V: ready to\nboth A and B: two things"}, {"text": "Conversations across cultures matter when each side is prepared to look at power relations as well as their own presuppositions.", "structureVi": "be prepared to + V: sẵn sàng\nA as well as B: cả A lẫn B", "structureEn": "be prepared to + V: ready to\nA as well as B: and also"}]$j$::jsonb),
  ('advanced', 'government-politics', 'Tính chính danh của chính sách phụ thuộc một phần vào việc quy trình ra quyết định có thể được kiểm tra hay không.', $j$[{"text": "The legitimacy of a policy depends in part on whether the decision-making process can be scrutinized.", "structureVi": "depend on whether: phụ thuộc vào việc liệu\nin part: một phần", "structureEn": "depend on whether: be decided by\nin part: partly"}, {"text": "Whether people accept a policy as legitimate partly depends on whether they can examine how it was decided.", "structureVi": "Whether + mệnh đề: việc liệu (chủ ngữ)\npartly: một phần", "structureEn": "Whether + clause: noun clause subject\npartly: to some extent"}]$j$::jsonb),
  ('advanced', 'government-politics', 'Một cuộc tham vấn công chúng chỉ có ý nghĩa khi ý kiến đóng góp được xem xét thực chất trước khi quyết định cuối cùng.', $j$[{"text": "A public consultation is meaningful only when the contributions are genuinely considered before the final decision.", "structureVi": "only when + mệnh đề: chỉ khi\nbe considered: được xem xét", "structureEn": "only when + clause: limiting condition\nbe considered: passive"}, {"text": "Asking the public for views counts for something only if their input is seriously weighed before a decision is made.", "structureVi": "count for something: có ý nghĩa\nbe weighed: được cân nhắc", "structureEn": "count for something: matter\nbe weighed: considered"}]$j$::jsonb),
  ('advanced', 'government-politics', 'Minh bạch dữ liệu cần đi kèm giải thích bối cảnh để tránh việc các con số bị diễn giải sai lệch.', $j$[{"text": "Data transparency should come with contextual explanation to prevent figures from being misinterpreted.", "structureVi": "come with: đi kèm\nprevent A from being + V3: ngăn A bị", "structureEn": "come with: accompany\nprevent A from being + V3: passive prevention"}, {"text": "Releasing data openly needs context so that the numbers are not read in the wrong way.", "structureVi": "need + danh từ: cần\nso that + mệnh đề: để", "structureEn": "need + noun: require\nso that + clause: purpose"}]$j$::jsonb),
  ('advanced', 'government-politics', 'Chính sách dài hạn thường gặp khó khăn khi lợi ích trước mắt tạo áp lực lên các nhà hoạch định.', $j$[{"text": "Long-term policies often run into difficulties when short-term interests put pressure on policymakers.", "structureVi": "run into difficulties: gặp khó khăn\nput pressure on: gây áp lực lên", "structureEn": "run into difficulties: encounter problems\nput pressure on: push"}, {"text": "Policies meant for the long run tend to struggle when immediate interests weigh on the people making them.", "structureVi": "tend to + V: có xu hướng\nweigh on: đè nặng lên", "structureEn": "tend to + V: usually\nweigh on: burden"}]$j$::jsonb),
  ('advanced', 'government-politics', 'Cơ chế giám sát độc lập có thể tăng trách nhiệm giải trình nếu được bảo vệ khỏi can thiệp không phù hợp.', $j$[{"text": "Independent oversight mechanisms can increase accountability if they are protected from inappropriate interference.", "structureVi": "can + V: có thể\nbe protected from: được bảo vệ khỏi", "structureEn": "can + V: possibility\nbe protected from: guarded against"}, {"text": "Watchdog bodies can make officials more answerable as long as they are shielded from improper interference.", "structureVi": "make + người + tính từ: khiến\nbe shielded from: được che chắn khỏi", "structureEn": "make + person + adjective: cause\nbe shielded from: protected from"}]$j$::jsonb),
  ('advanced', 'government-politics', 'Việc đo lường hiệu quả quản trị nên tính đến chất lượng dịch vụ và mức độ tin cậy của người dân.', $j$[{"text": "Measuring the effectiveness of governance should take into account the quality of services and the level of public trust.", "structureVi": "Measuring: V-ing làm chủ ngữ\nthe level of: mức độ", "structureEn": "Measuring: gerund subject\nthe level of: degree"}, {"text": "To gauge how well a government performs, we should look at how good its services are and how far citizens trust it.", "structureVi": "To + V: để\nhow far + mệnh đề: mức độ", "structureEn": "To + V: purpose\nhow far + clause: extent"}]$j$::jsonb),
  ('advanced', 'government-politics', 'Thông tin sai lệch lan rộng nhanh hơn khi thông điệp chính thức thiếu nhất quán hoặc khó tiếp cận.', $j$[{"text": "Misinformation spreads faster when official messages are inconsistent or hard to access.", "structureVi": "spread faster: lan nhanh hơn\nwhen + mệnh đề: khi", "structureEn": "spread faster: comparative\nwhen + clause: condition"}, {"text": "False information travels more quickly if government announcements contradict each other or are difficult to find.", "structureVi": "more quickly: nhanh hơn\ncontradict each other: mâu thuẫn nhau", "structureEn": "more quickly: comparative adverb\ncontradict each other: be inconsistent"}]$j$::jsonb),
  ('advanced', 'government-politics', 'Phân cấp quyền lực có thể giúp quyết định sát nhu cầu địa phương nhưng cũng đòi hỏi năng lực giám sát tương xứng.', $j$[{"text": "Decentralizing power can help decisions fit local needs but also requires matching oversight capacity.", "structureVi": "can help + V: có thể giúp\nbut also + V: nhưng cũng", "structureEn": "can help + V: may assist\nbut also + V: contrast"}, {"text": "Devolving authority may tailor decisions to local needs, although it demands an equal ability to supervise.", "structureVi": "tailor A to B: điều chỉnh\nalthough + mệnh đề: mặc dù", "structureEn": "tailor A to B: adapt\nalthough + clause: contrast"}]$j$::jsonb),
  ('advanced', 'government-politics', 'Một chính sách công bằng cần xem xét liệu chi phí và lợi ích có được phân bổ hợp lý giữa các nhóm hay không.', $j$[{"text": "A fair policy should consider whether costs and benefits are reasonably shared among different groups.", "structureVi": "consider whether: xem xét liệu\nbe shared among: được chia sẻ giữa", "structureEn": "consider whether: think about if\nbe shared among: distributed between"}, {"text": "Good policy should ask if the burdens and gains are spread fairly across groups.", "structureVi": "ask if: hỏi liệu\nbe spread across: được phân bổ", "structureEn": "ask if: wonder whether\nbe spread across: distributed"}]$j$::jsonb),
  ('advanced', 'government-politics', 'Tranh luận dân chủ hiệu quả đòi hỏi người tham gia phân biệt bằng chứng có thể kiểm chứng với quan điểm cá nhân.', $j$[{"text": "Effective democratic debate requires participants to distinguish verifiable evidence from personal opinion.", "structureVi": "require + người + to + V: đòi hỏi ai\ndistinguish A from B: phân biệt", "structureEn": "require + person + to + V: need someone to\ndistinguish A from B: tell apart"}, {"text": "For democratic discussion to work well, people have to separate facts that can be checked from their own views.", "structureVi": "For + danh từ + to + V: để...\nfacts that can be checked: mệnh đề quan hệ", "structureEn": "For + noun + to + V: purpose\nfacts that can be checked: relative clause"}]$j$::jsonb),
  ('advanced', 'history-geography', 'Cách diễn giải một sự kiện lịch sử thường thay đổi khi những nguồn tư liệu mới được phát hiện.', $j$[{"text": "The way a historical event is interpreted often changes when new sources are discovered.", "structureVi": "The way + mệnh đề: cách mà\nwhen + mệnh đề: khi", "structureEn": "The way + clause: manner\nwhen + clause: time"}, {"text": "Interpretations of historical events frequently shift once fresh documents come to light.", "structureVi": "shift: thay đổi\ncome to light: được phát hiện", "structureEn": "shift: change\ncome to light: be discovered"}]$j$::jsonb),
  ('advanced', 'history-geography', 'Địa lý không quyết định hoàn toàn sự phát triển của xã hội nhưng tạo ra những cơ hội và giới hạn khác nhau.', $j$[{"text": "Geography doesn't completely determine a society's development, but it creates different opportunities and limits.", "structureVi": "not completely: không hoàn toàn\nbut: nhưng", "structureEn": "not completely: partial negation\nbut: contrast"}, {"text": "Although a society's growth isn't entirely decided by its geography, the land offers varying chances and constraints.", "structureVi": "Although + mệnh đề: mặc dù\nentirely: hoàn toàn", "structureEn": "Although + clause: contrast\nentirely: completely"}]$j$::jsonb),
  ('advanced', 'history-geography', 'Việc bảo tồn di tích cần cân bằng tính xác thực lịch sử với nhu cầu sử dụng của cộng đồng hiện tại.', $j$[{"text": "Preserving historic sites needs to balance historical authenticity with the needs of today's community.", "structureVi": "balance A with B: cân bằng\nthe needs of: nhu cầu của", "structureEn": "balance A with B: weigh\nthe needs of: requirements"}, {"text": "Protecting monuments requires a balance between their historical accuracy and what the present community wants to use them for.", "structureVi": "a balance between A and B: sự cân bằng\nwhat + mệnh đề: điều mà", "structureEn": "a balance between A and B: equal consideration\nwhat + clause: noun clause"}]$j$::jsonb),
  ('advanced', 'history-geography', 'Bản đồ cổ phản ánh không chỉ hiểu biết địa lý mà còn cả mục đích chính trị của người tạo ra chúng.', $j$[{"text": "Old maps reflect not only geographical knowledge but also the political purposes of their makers.", "structureVi": "not only A but also B: không chỉ A mà còn B\ntheir makers: người tạo ra chúng", "structureEn": "not only A but also B: both\ntheir makers: those who made them"}, {"text": "Ancient maps show what people knew about geography as well as what their creators wanted politically.", "structureVi": "A as well as B: cả A lẫn B\nwhat + mệnh đề: điều mà", "structureEn": "A as well as B: and also\nwhat + clause: noun clause"}]$j$::jsonb),
  ('advanced', 'history-geography', 'Sự suy tàn của một đô thị thường bắt nguồn từ nhiều yếu tố tương tác chứ hiếm khi do một nguyên nhân duy nhất.', $j$[{"text": "The decline of a city often stems from several interacting factors and rarely from a single cause.", "structureVi": "stem from: bắt nguồn từ\nrarely + từ: hiếm khi", "structureEn": "stem from: originate in\nrarely + from: seldom"}, {"text": "Cities usually decay because of a number of factors acting together, hardly ever because of just one.", "structureVi": "because of: vì\nhardly ever: hầu như không bao giờ", "structureEn": "because of: reason\nhardly ever: almost never"}]$j$::jsonb),
  ('advanced', 'history-geography', 'Biến đổi khí hậu trong quá khứ có thể giúp nhà nghiên cứu hiểu khả năng thích nghi của các cộng đồng.', $j$[{"text": "Climate change in the past can help researchers understand how communities were able to adapt.", "structureVi": "help + người + V: giúp\nhow + mệnh đề: cách mà", "structureEn": "help + person + V: assist\nhow + clause: indirect question"}, {"text": "Studying earlier climate shifts may show researchers how societies managed to adjust.", "structureVi": "manage to + V: xoay xở để\nshow + người + how: cho ai thấy", "structureEn": "manage to + V: succeed in\nshow + person + how: reveal"}]$j$::jsonb),
  ('advanced', 'history-geography', 'Di sản khảo cổ cần được ghi chép cẩn thận trước khi khai quật vì quá trình này có thể làm mất ngữ cảnh ban đầu.', $j$[{"text": "Archaeological heritage needs to be carefully documented before excavation because the process can destroy the original context.", "structureVi": "need to be + V3: cần được\nbecause + mệnh đề: vì", "structureEn": "need to be + V3: passive necessity\nbecause + clause: reason"}, {"text": "Archaeological sites should be recorded thoroughly prior to digging, since excavating may erase their original setting.", "structureVi": "prior to + V-ing: trước khi\nsince + mệnh đề: vì", "structureEn": "prior to + V-ing: before\nsince + clause: reason"}]$j$::jsonb),
  ('advanced', 'history-geography', 'Các tuyến di cư đã góp phần trao đổi ngôn ngữ, kỹ thuật và tập quán giữa những khu vực xa nhau.', $j$[{"text": "Migration routes contributed to the exchange of languages, techniques and customs between distant regions.", "structureVi": "contribute to: góp phần\nbetween + danh từ: giữa", "structureEn": "contribute to: help bring about\nbetween + noun: connecting"}, {"text": "Paths of migration helped spread languages, skills and traditions among places far from each other.", "structureVi": "help + V: giúp\namong + danh từ: giữa", "structureEn": "help + V: assist\namong + noun: between several"}]$j$::jsonb),
  ('advanced', 'history-geography', 'Ranh giới quốc gia hiện đại đôi khi che khuất những mạng lưới văn hóa từng tồn tại xuyên vùng.', $j$[{"text": "Modern national borders sometimes obscure the cultural networks that once spanned regions.", "structureVi": "obscure + danh từ: che khuất\nthat once + V: từng", "structureEn": "obscure + noun: hide\nthat once + V: past relative clause"}, {"text": "Today's national boundaries can hide the cultural links that used to stretch across regions.", "structureVi": "can + V: có thể\nused to + V: từng", "structureEn": "can + V: possibility\nused to + V: past state"}]$j$::jsonb),
  ('advanced', 'history-geography', 'Hiểu lịch sử địa phương giúp giải thích vì sao cùng một chính sách có thể tạo ra kết quả khác nhau ở mỗi nơi.', $j$[{"text": "Understanding local history helps explain why the same policy can produce different results in different places.", "structureVi": "V-ing làm chủ ngữ: hiểu\nexplain why: giải thích tại sao", "structureEn": "V-ing as subject: understanding\nexplain why: give the reason"}, {"text": "Knowing a place's history makes it clearer why one policy can have varied outcomes from area to area.", "structureVi": "make it + tính từ + why: khiến rõ ràng vì sao\nfrom area to area: ở từng khu vực", "structureEn": "make it + adjective + why: noun clause object\nfrom area to area: place by place"}]$j$::jsonb),
  ('advanced', 'sports-fitness', 'Thành tích thi đấu bền vững đòi hỏi chu kỳ tập luyện cân bằng giữa tải trọng, phục hồi và đánh giá tiến bộ.', $j$[{"text": "Sustainable athletic performance requires a training cycle that balances workload, recovery and progress assessment.", "structureVi": "require + danh từ: đòi hỏi\na cycle that + V: chu kỳ mà", "structureEn": "require + noun: need\na cycle that + V: relative clause"}, {"text": "To keep performing well over time, athletes need a training routine that balances effort, rest and evaluation of their progress.", "structureVi": "To + V: để\na routine that + V: mệnh đề quan hệ", "structureEn": "To + V: purpose\na routine that + V: relative clause"}]$j$::jsonb),
  ('advanced', 'sports-fitness', 'Chiến thuật hiệu quả cần được điều chỉnh theo diễn biến trận đấu thay vì áp dụng cứng nhắc từ đầu đến cuối.', $j$[{"text": "Effective tactics should be adjusted according to how the match develops instead of being applied rigidly from start to finish.", "structureVi": "should be + V3: nên được\ninstead of being + V3: thay vì bị", "structureEn": "should be + V3: passive advice\ninstead of being + V3: passive gerund"}, {"text": "A good game plan has to change as the match unfolds rather than being followed stubbornly throughout.", "structureVi": "as + mệnh đề: khi\nrather than being + V3: thay vì bị", "structureEn": "as + clause: while\nrather than being + V3: passive gerund"}]$j$::jsonb),
  ('advanced', 'sports-fitness', 'Việc tiếp cận thể thao nên được xem là vấn đề sức khỏe cộng đồng chứ không chỉ là lựa chọn cá nhân.', $j$[{"text": "Access to sport should be seen as a public health issue, not just an individual choice.", "structureVi": "should be seen as: nên được xem là\nnot just: không chỉ", "structureEn": "should be seen as: passive advice\nnot just: more than"}, {"text": "Being able to play sport ought to be viewed as a matter of community health and not merely personal preference.", "structureVi": "be viewed as: được coi là\nnot merely: không chỉ", "structureEn": "be viewed as: considered\nnot merely: not only"}]$j$::jsonb),
  ('advanced', 'sports-fitness', 'Dữ liệu theo dõi vận động có thể hỗ trợ huấn luyện nhưng cần được diễn giải trong bối cảnh của từng vận động viên.', $j$[{"text": "Movement-tracking data can support coaching but must be interpreted in the context of each athlete.", "structureVi": "can + V: có thể\nmust be + V3: phải được", "structureEn": "can + V: possibility\nmust be + V3: passive obligation"}, {"text": "Performance data may help trainers, provided it is understood in light of the individual athlete.", "structureVi": "help + người: giúp ai\nin light of: dựa trên", "structureEn": "help + person: assist\nin light of: considering"}]$j$::jsonb),
  ('advanced', 'sports-fitness', 'Áp lực thành tích quá mức có thể làm suy giảm động lực nếu mục tiêu không phù hợp với khả năng thực tế.', $j$[{"text": "Excessive performance pressure can undermine motivation if the goals do not match realistic ability.", "structureVi": "undermine + danh từ: làm suy giảm\nmatch + danh từ: phù hợp với", "structureEn": "undermine + noun: weaken\nmatch + noun: fit"}, {"text": "Too much pressure to achieve may reduce someone's drive when targets are beyond what they can realistically do.", "structureVi": "too much + danh từ: quá nhiều\nbeyond + danh từ: vượt quá", "structureEn": "too much + noun: excessive\nbeyond + noun: more than"}]$j$::jsonb),
  ('advanced', 'sports-fitness', 'Một đội mạnh không chỉ có những cá nhân xuất sắc mà còn biết phối hợp và thích nghi khi kế hoạch thay đổi.', $j$[{"text": "A strong team doesn't only have outstanding individuals but also knows how to cooperate and adapt when plans change.", "structureVi": "not only A but also B: không chỉ A mà còn B\nknow how to + V: biết cách", "structureEn": "not only A but also B: both\nknow how to + V: have the ability"}, {"text": "What makes a team strong is not just excellent players but the ability to work together and adjust when the plan changes.", "structureVi": "What + V: điều khiến (chủ ngữ)\nthe ability to + V: khả năng", "structureEn": "What + V: noun clause subject\nthe ability to + V: capacity"}]$j$::jsonb),
  ('advanced', 'sports-fitness', 'Cơ sở thể thao công cộng cần được thiết kế để nhiều lứa tuổi và mức thể lực có thể sử dụng an toàn.', $j$[{"text": "Public sports facilities need to be designed so that people of many ages and fitness levels can use them safely.", "structureVi": "need to be + V3: cần được\nso that + mệnh đề: để mà", "structureEn": "need to be + V3: passive necessity\nso that + clause: purpose"}, {"text": "Community sports venues should be built in a way that lets different ages and abilities exercise safely.", "structureVi": "should be + V3: nên được\nin a way that: theo cách", "structureEn": "should be + V3: passive advice\nin a way that: manner"}]$j$::jsonb),
  ('advanced', 'sports-fitness', 'Phục hồi sau chấn thương thường đòi hỏi kiên nhẫn và phối hợp giữa chuyên gia với người tập.', $j$[{"text": "Recovering from an injury usually requires patience and cooperation between specialists and the person training.", "structureVi": "recover from: phục hồi sau\ncooperation between: sự phối hợp giữa", "structureEn": "recover from: get better after\ncooperation between: working together"}, {"text": "Getting over an injury generally takes patience, and experts and athletes have to work together.", "structureVi": "get over: vượt qua\ntake + danh từ: cần", "structureEn": "get over: recover from\ntake + noun: require"}]$j$::jsonb),
  ('advanced', 'sports-fitness', 'Công bằng trong thi đấu phụ thuộc vào quy tắc rõ ràng và cách thực thi nhất quán.', $j$[{"text": "Fairness in competition depends on clear rules and consistent enforcement.", "structureVi": "depend on: phụ thuộc vào\nclear rules: quy tắc rõ ràng", "structureEn": "depend on: be determined by\nclear rules: unambiguous regulations"}, {"text": "A level playing field relies on rules that are clear and applied consistently.", "structureVi": "rely on: dựa vào\nrules that are + V3: mệnh đề quan hệ", "structureEn": "rely on: depend on\nrules that are + V3: relative clause"}]$j$::jsonb),
  ('advanced', 'sports-fitness', 'Thói quen vận động lâu dài dễ duy trì hơn khi hoạt động thể chất gắn với niềm vui thay vì nghĩa vụ.', $j$[{"text": "A long-term exercise habit is easier to maintain when physical activity is linked to enjoyment rather than obligation.", "structureVi": "easier to + V: dễ hơn\nrather than: hơn là", "structureEn": "easier to + V: comparative\nrather than: instead of"}, {"text": "People stick with exercise for years more readily if it brings them pleasure instead of feeling like a duty.", "structureVi": "stick with: kiên trì với\nmore readily: dễ dàng hơn", "structureEn": "stick with: continue\nmore readily: comparative adverb"}]$j$::jsonb),
  ('advanced', 'arts-literature', 'Một tác phẩm có sức sống lâu dài thường cho phép nhiều cách diễn giải mà không mất đi tính nhất quán nội tại.', $j$[{"text": "A work with lasting vitality usually allows multiple interpretations without losing its internal consistency.", "structureVi": "allow + danh từ: cho phép\nwithout + V-ing: mà không", "structureEn": "allow + noun: permit\nwithout + V-ing: not losing"}, {"text": "Artworks that stay alive for a long time tend to be open to many readings while remaining coherent.", "structureVi": "tend to + V: có xu hướng\nwhile + V-ing: trong khi", "structureEn": "tend to + V: usually\nwhile + V-ing: at the same time"}]$j$::jsonb),
  ('advanced', 'arts-literature', 'Dịch văn học đòi hỏi cân bằng giữa sắc thái của nguyên tác và khả năng tiếp nhận của độc giả mới.', $j$[{"text": "Literary translation requires balancing the nuances of the original with the reception of new readers.", "structureVi": "require + V-ing: đòi hỏi\nbalance A with B: cân bằng", "structureEn": "require + V-ing: need\nbalance A with B: weigh"}, {"text": "Translating literature means finding a balance between the original's subtle shades and what new readers can take in.", "structureVi": "mean + V-ing: có nghĩa là\nwhat + mệnh đề: điều mà", "structureEn": "mean + V-ing: involve\nwhat + clause: noun clause"}]$j$::jsonb),
  ('advanced', 'arts-literature', 'Việc số hóa tác phẩm giúp mở rộng khả năng tiếp cận nhưng không thay thế hoàn toàn trải nghiệm trực tiếp.', $j$[{"text": "Digitizing artworks expands access but does not entirely replace the experience of seeing them in person.", "structureVi": "V-ing làm chủ ngữ: số hóa\nnot entirely: không hoàn toàn", "structureEn": "V-ing as subject: digitizing\nnot entirely: partial negation"}, {"text": "Putting art online makes it easier to reach, though it can't fully substitute for seeing it face to face.", "structureVi": "make it easier to + V: giúp dễ hơn\nsubstitute for: thay thế", "structureEn": "make it easier to + V: facilitate\nsubstitute for: replace"}]$j$::jsonb),
  ('advanced', 'arts-literature', 'Phê bình nghệ thuật thuyết phục cần đặt tác phẩm trong bối cảnh mà vẫn đánh giá được những lựa chọn hình thức cụ thể.', $j$[{"text": "Persuasive art criticism needs to place a work in context while still assessing its specific formal choices.", "structureVi": "need to + V: cần\nwhile still + V-ing: trong khi vẫn", "structureEn": "need to + V: necessity\nwhile still + V-ing: simultaneously"}, {"text": "A convincing critique sets the piece in its context and also judges the particular decisions of form.", "structureVi": "set A in B: đặt A vào B\nthe decisions of form: lựa chọn hình thức", "structureEn": "set A in B: place\nthe decisions of form: formal choices"}]$j$::jsonb),
  ('advanced', 'arts-literature', 'Người kể chuyện không đáng tin cậy khiến độc giả phải liên tục xem xét khoảng cách giữa lời kể và sự kiện.', $j$[{"text": "An unreliable narrator forces readers to keep considering the gap between what is told and what happens.", "structureVi": "force + người + to + V: buộc ai\nthe gap between A and B: khoảng cách giữa", "structureEn": "force + person + to + V: compel\nthe gap between A and B: difference"}, {"text": "When the narrator can't be trusted, readers have to continually weigh the account against the actual events.", "structureVi": "When + mệnh đề: khi\nweigh A against B: cân nhắc", "structureEn": "When + clause: time\nweigh A against B: compare"}]$j$::jsonb),
  ('advanced', 'arts-literature', 'Nghệ thuật công cộng có thể khơi gợi đối thoại khi cộng đồng được tham gia từ khâu hình thành ý tưởng.', $j$[{"text": "Public art can spark dialogue when the community is involved from the stage of forming ideas.", "structureVi": "can + V: có thể\nfrom the stage of: từ khâu", "structureEn": "can + V: possibility\nfrom the stage of: starting at"}, {"text": "Art in public spaces can start conversations if local people take part right from the idea stage.", "structureVi": "start conversations: khơi gợi đối thoại\ntake part: tham gia", "structureEn": "start conversations: prompt discussion\ntake part: participate"}]$j$::jsonb),
  ('advanced', 'arts-literature', 'Một bản chuyển thể thành công không nhất thiết trung thành từng chi tiết mà cần giữ được tinh thần cốt lõi.', $j$[{"text": "A successful adaptation does not necessarily stay faithful to every detail but needs to keep the core spirit.", "structureVi": "not necessarily: không nhất thiết\nneed to + V: cần", "structureEn": "not necessarily: not always\nneed to + V: necessity"}, {"text": "A good screen version needn't copy each detail as long as it preserves the essential spirit of the original.", "structureVi": "needn't + V: không cần\nas long as + mệnh đề: miễn là", "structureEn": "needn't + V: not necessary\nas long as + clause: condition"}]$j$::jsonb),
  ('advanced', 'arts-literature', 'Thị trường có thể hỗ trợ nghệ sĩ sống bằng nghề nhưng cũng tạo áp lực lặp lại những gì đã bán chạy.', $j$[{"text": "The market can help artists make a living from their work but also creates pressure to repeat what has sold well.", "structureVi": "help + người + V: giúp\nwhat has sold well: điều đã bán chạy", "structureEn": "help + person + V: assist\nwhat has sold well: noun clause"}, {"text": "Commercial demand lets artists earn a living, yet it pushes them to keep doing whatever has been successful.", "structureVi": "let + người + V: cho phép\nwhatever + mệnh đề: bất cứ điều gì", "structureEn": "let + person + V: allow\nwhatever + clause: anything that"}]$j$::jsonb),
  ('advanced', 'arts-literature', 'Việc lưu trữ bản thảo và tư liệu sáng tác giúp thế hệ sau hiểu quá trình hình thành tác phẩm.', $j$[{"text": "Archiving manuscripts and creative materials helps later generations understand how a work came into being.", "structureVi": "V-ing làm chủ ngữ: lưu trữ\nhow + mệnh đề: cách mà", "structureEn": "V-ing as subject: archiving\nhow + clause: indirect question"}, {"text": "Keeping drafts and source materials lets future generations see how a piece was created.", "structureVi": "let + người + V: cho phép\nhow + mệnh đề: cách", "structureEn": "let + person + V: allow\nhow + clause: indirect question"}]$j$::jsonb),
  ('advanced', 'arts-literature', 'Tác phẩm nghệ thuật đôi khi đặt ra câu hỏi quan trọng hơn việc đưa ra một thông điệp rõ ràng.', $j$[{"text": "Works of art sometimes raise more important questions than deliver a clear message.", "structureVi": "more important questions than: câu hỏi quan trọng hơn\nraise: đặt ra", "structureEn": "more important questions than: comparison\nraise: bring up"}, {"text": "At times art matters more for the questions it poses than for any clear message it gives.", "structureVi": "matter more for: quan trọng hơn vì\nat times: đôi khi", "structureEn": "matter more for: be more important because of\nat times: sometimes"}]$j$::jsonb),
  ('advanced', 'religion-spirituality', 'Đối thoại giữa các truyền thống tín ngưỡng cần tránh giả định rằng mọi thành viên đều thực hành niềm tin theo cùng một cách.', $j$[{"text": "Dialogue between faith traditions should avoid assuming that all members practice their beliefs in the same way.", "structureVi": "avoid + V-ing: tránh\nassume that: giả định rằng", "structureEn": "avoid + V-ing: not do\nassume that: take for granted"}, {"text": "Conversations among religions need to steer clear of the idea that every follower observes their faith identically.", "structureVi": "steer clear of: tránh\nthe idea that: ý nghĩ rằng", "structureEn": "steer clear of: avoid\nthe idea that: appositive clause"}]$j$::jsonb),
  ('advanced', 'religion-spirituality', 'Thực hành chiêm nghiệm có thể giúp một số người hiểu rõ giá trị cá nhân nhưng không thay thế việc giải quyết vấn đề thực tế.', $j$[{"text": "Contemplative practice can help some people understand their personal values but doesn't replace solving practical problems.", "structureVi": "can help + V: có thể giúp\nreplace + danh từ: thay thế", "structureEn": "can help + V: may assist\nreplace + noun: substitute"}, {"text": "Reflection may give certain people a clearer sense of their values, though it can't take the place of dealing with real-life issues.", "structureVi": "give + người + vật: mang lại\ntake the place of: thay thế", "structureEn": "give + person + thing: provide\ntake the place of: substitute"}]$j$::jsonb),
  ('advanced', 'religion-spirituality', 'Không gian tôn giáo vừa lưu giữ di sản tinh thần vừa phản ánh lịch sử và đời sống của cộng đồng.', $j$[{"text": "Religious spaces both preserve spiritual heritage and reflect the history and life of the community.", "structureVi": "both A and B: vừa A vừa B\nreflect + danh từ: phản ánh", "structureEn": "both A and B: two roles\nreflect + noun: show"}, {"text": "Places of worship hold on to spiritual heritage while also mirroring a community's history and daily life.", "structureVi": "hold on to: giữ gìn\nwhile also + V-ing: đồng thời", "structureEn": "hold on to: keep\nwhile also + V-ing: at the same time"}]$j$::jsonb),
  ('advanced', 'religion-spirituality', 'Tôn trọng tự do tín ngưỡng bao gồm cả quyền thay đổi niềm tin hoặc không theo một tôn giáo nào.', $j$[{"text": "Respecting freedom of belief includes the right to change one's beliefs or not to follow any religion.", "structureVi": "include + danh từ: bao gồm\nthe right to + V: quyền", "structureEn": "include + noun: contain\nthe right to + V: entitlement"}, {"text": "Religious freedom means being free to switch beliefs or to belong to no faith at all.", "structureVi": "mean + V-ing: có nghĩa là\nbe free to + V: được tự do", "structureEn": "mean + V-ing: involve\nbe free to + V: permitted to"}]$j$::jsonb),
  ('advanced', 'religion-spirituality', 'Các hoạt động thiện nguyện có sức lan tỏa hơn khi lòng trắc ẩn được chuyển thành hỗ trợ lâu dài và có tổ chức.', $j$[{"text": "Charitable activities spread further when compassion is turned into long-term, organized support.", "structureVi": "spread further: lan tỏa hơn\nbe turned into: được chuyển thành", "structureEn": "spread further: reach more people\nbe turned into: passive change"}, {"text": "Charity has a wider reach if kindness becomes lasting and well-organized help.", "structureVi": "have a wider reach: có tầm ảnh hưởng rộng hơn\nbecome + tính từ: trở thành", "structureEn": "have a wider reach: comparative\nbecome + adjective: change into"}]$j$::jsonb),
  ('advanced', 'religion-spirituality', 'Nghi lễ truyền thống có thể duy trì cảm giác gắn kết ngay cả khi ý nghĩa của chúng thay đổi qua các thế hệ.', $j$[{"text": "Traditional rituals can sustain a sense of belonging even when their meanings change across generations.", "structureVi": "can + V: có thể\neven when + mệnh đề: ngay cả khi", "structureEn": "can + V: possibility\neven when + clause: despite"}, {"text": "Time-honored ceremonies may keep people feeling connected although what they mean shifts from one generation to the next.", "structureVi": "keep + người + V-ing: giữ cho\nalthough + mệnh đề: mặc dù", "structureEn": "keep + person + V-ing: make continue\nalthough + clause: contrast"}]$j$::jsonb),
  ('advanced', 'religion-spirituality', 'Sự khác biệt trong niềm tin không nhất thiết dẫn đến chia rẽ nếu các bên thống nhất những nguyên tắc chung về phẩm giá.', $j$[{"text": "Differences in belief do not necessarily lead to division if the parties agree on common principles of dignity.", "structureVi": "lead to: dẫn đến\nagree on: thống nhất", "structureEn": "lead to: cause\nagree on: reach consensus"}, {"text": "People with different convictions needn't be divided provided they share basic principles about human dignity.", "structureVi": "needn't + V: không cần\nprovided (that): miễn là", "structureEn": "needn't + V: not necessary\nprovided (that): condition"}]$j$::jsonb),
  ('advanced', 'religion-spirituality', 'Việc nghiên cứu tôn giáo cần phân biệt giữa mô tả thực hành và đánh giá niềm tin của người tham gia.', $j$[{"text": "The study of religion needs to distinguish between describing practices and judging participants' beliefs.", "structureVi": "distinguish between A and B: phân biệt\ndescribe + danh từ: mô tả", "structureEn": "distinguish between A and B: tell apart\ndescribe + noun: depict"}, {"text": "Researching religion requires a clear line between explaining what people do and evaluating what they believe.", "structureVi": "a line between A and B: ranh giới\nwhat + mệnh đề: điều mà", "structureEn": "a line between A and B: boundary\nwhat + clause: noun clause"}]$j$::jsonb),
  ('advanced', 'religion-spirituality', 'Đời sống tinh thần của mỗi người thường chịu ảnh hưởng đồng thời từ gia đình, cộng đồng và trải nghiệm riêng.', $j$[{"text": "Each person's spiritual life is usually influenced simultaneously by family, community and personal experience.", "structureVi": "be influenced by: chịu ảnh hưởng\nsimultaneously: đồng thời", "structureEn": "be influenced by: passive\nsimultaneously: at once"}, {"text": "How someone lives spiritually is typically shaped at once by their family, their community and what they have personally been through.", "structureVi": "How + mệnh đề: cách mà (chủ ngữ)\nbe shaped by: được hình thành bởi", "structureEn": "How + clause: noun clause subject\nbe shaped by: influenced by"}]$j$::jsonb),
  ('advanced', 'religion-spirituality', 'Một xã hội hòa hợp không đòi hỏi mọi người có cùng niềm tin mà cần bảo đảm họ được đối xử công bằng.', $j$[{"text": "A harmonious society does not require everyone to share the same beliefs but needs to ensure that they are treated fairly.", "structureVi": "not require + người + to + V: không đòi hỏi ai\nensure that: bảo đảm rằng", "structureEn": "not require + person + to + V: not demand\nensure that: make certain"}, {"text": "Social harmony doesn't depend on people believing the same things; it depends on making sure everyone is treated equally.", "structureVi": "depend on + V-ing: phụ thuộc vào việc\nmake sure that: đảm bảo", "structureEn": "depend on + V-ing: rely on doing\nmake sure that: ensure"}]$j$::jsonb),
  ('advanced', 'law-justice', 'Nguyên tắc bình đẳng trước pháp luật chỉ có ý nghĩa khi mọi người có khả năng tiếp cận cơ chế bảo vệ quyền lợi.', $j$[{"text": "The principle of equality before the law only has meaning when everyone is able to access mechanisms that protect their rights.", "structureVi": "only + V: chỉ\nbe able to + V: có thể", "structureEn": "only + V: restriction\nbe able to + V: can"}, {"text": "Equality before the law counts for little unless all people can use the means of defending their rights.", "structureVi": "count for little: ít có ý nghĩa\nunless + mệnh đề: trừ khi", "structureEn": "count for little: matter very little\nunless + clause: if not"}]$j$::jsonb),
  ('advanced', 'law-justice', 'Quy định rõ ràng giúp giảm tranh chấp nhưng vẫn cần cách áp dụng linh hoạt trước những tình huống đặc biệt.', $j$[{"text": "Clear regulations reduce disputes but still need flexible application in special situations.", "structureVi": "reduce + danh từ: giảm\nin special situations: trong tình huống đặc biệt", "structureEn": "reduce + noun: lessen\nin special situations: in exceptional cases"}, {"text": "Well-defined rules cut down on conflict, yet they must be applied with some flexibility to unusual cases.", "structureVi": "cut down on: giảm\nmust be + V3: phải được", "structureEn": "cut down on: reduce\nmust be + V3: passive obligation"}]$j$::jsonb),
  ('advanced', 'law-justice', 'Một hệ thống tư pháp đáng tin cậy phải bảo đảm cả tính độc lập lẫn khả năng giải trình về quyết định.', $j$[{"text": "A trustworthy justice system must ensure both independence and accountability for its decisions.", "structureVi": "must ensure: phải bảo đảm\nboth A and B: cả A lẫn B", "structureEn": "must ensure: obligation\nboth A and B: two qualities"}, {"text": "For a legal system to be trusted, it has to be independent and answerable for its rulings.", "structureVi": "For + danh từ + to + V: để\nanswerable for: chịu trách nhiệm về", "structureEn": "For + noun + to + V: purpose\nanswerable for: accountable"}]$j$::jsonb),
  ('advanced', 'law-justice', 'Việc thu thập dữ liệu phục vụ điều tra cần được cân bằng với quyền riêng tư và các biện pháp bảo vệ phù hợp.', $j$[{"text": "Collecting data for investigations needs to be balanced against privacy rights and appropriate safeguards.", "structureVi": "need to be + V3: cần được\nbe balanced against: được cân bằng với", "structureEn": "need to be + V3: passive necessity\nbe balanced against: weighed with"}, {"text": "Gathering evidence for an inquiry must be weighed against people's privacy and suitable protections.", "structureVi": "must be + V3: phải được\nbe weighed against: được cân nhắc", "structureEn": "must be + V3: passive obligation\nbe weighed against: compared with"}]$j$::jsonb),
  ('advanced', 'law-justice', 'Hòa giải có thể tiết kiệm thời gian trong một số tranh chấp nhưng không nên thay thế bảo vệ quyền cơ bản.', $j$[{"text": "Mediation can save time in some disputes but should not replace the protection of fundamental rights.", "structureVi": "can + V: có thể\nshould not + V: không nên", "structureEn": "can + V: possibility\nshould not + V: advice"}, {"text": "Settling a dispute through a mediator may be quicker in some cases, but it must not take the place of safeguarding basic rights.", "structureVi": "through + danh từ: thông qua\ntake the place of: thay thế", "structureEn": "through + noun: by means of\ntake the place of: replace"}]$j$::jsonb),
  ('advanced', 'law-justice', 'Phổ biến pháp luật hiệu quả đòi hỏi ví dụ thực tế và ngôn ngữ dễ hiểu thay vì chỉ công bố văn bản chuyên môn.', $j$[{"text": "Effective legal education requires real examples and plain language rather than just publishing technical texts.", "structureVi": "require + danh từ: đòi hỏi\nrather than just + V-ing: thay vì chỉ", "structureEn": "require + noun: need\nrather than just + V-ing: instead of only"}, {"text": "Teaching people the law well calls for practical cases and easy wording instead of merely releasing specialist documents.", "structureVi": "call for: đòi hỏi\ninstead of merely + V-ing: thay vì chỉ", "structureEn": "call for: require\ninstead of merely + V-ing: not only"}]$j$::jsonb),
  ('advanced', 'law-justice', 'Chế tài quá nghiêm khắc không nhất thiết ngăn vi phạm nếu khả năng phát hiện và thực thi còn thấp.', $j$[{"text": "Overly harsh penalties do not necessarily deter violations if the likelihood of detection and enforcement remains low.", "structureVi": "not necessarily + V: không nhất thiết\nif + mệnh đề: nếu", "structureEn": "not necessarily + V: not always\nif + clause: condition"}, {"text": "Severe punishments won't always discourage offenses when there is little chance of being caught and penalized.", "structureVi": "won't always + V: không phải lúc nào cũng\nlittle chance of + V-ing: ít khả năng", "structureEn": "won't always + V: partial negation\nlittle chance of + V-ing: low probability"}]$j$::jsonb),
  ('advanced', 'law-justice', 'Hợp đồng công bằng cần phân bổ rủi ro minh bạch thay vì chuyển toàn bộ trách nhiệm sang bên yếu thế.', $j$[{"text": "A fair contract needs to allocate risks transparently instead of shifting all responsibility to the weaker party.", "structureVi": "need to + V: cần\ninstead of + V-ing: thay vì", "structureEn": "need to + V: necessity\ninstead of + V-ing: rather than"}, {"text": "Fair agreements should share out the risks openly rather than putting every burden on the weaker side.", "structureVi": "should + V: nên\nput a burden on: đặt gánh nặng lên", "structureEn": "should + V: advice\nput a burden on: impose"}]$j$::jsonb),
  ('advanced', 'law-justice', 'Bằng chứng cần được đánh giá theo độ tin cậy và ngữ cảnh chứ không chỉ theo số lượng tài liệu.', $j$[{"text": "Evidence should be assessed by its reliability and context, not just by the quantity of documents.", "structureVi": "should be + V3: nên được\nnot just: không chỉ", "structureEn": "should be + V3: passive advice\nnot just: more than"}, {"text": "We must judge proof on how trustworthy it is and in what setting it arose, rather than how many papers there are.", "structureVi": "judge A on B: đánh giá A dựa trên B\nrather than: thay vì", "structureEn": "judge A on B: assess by\nrather than: instead of"}]$j$::jsonb),
  ('advanced', 'law-justice', 'Niềm tin vào pháp luật tăng lên khi quy trình khiếu nại có thể tiếp cận và kết quả được giải thích rõ ràng.', $j$[{"text": "Trust in the law increases when the complaints process is accessible and the results are clearly explained.", "structureVi": "increase: tăng lên\nwhen + mệnh đề: khi", "structureEn": "increase: grow\nwhen + clause: condition"}, {"text": "People have more faith in the legal system if it is easy to file complaints and the outcomes are made clear.", "structureVi": "have faith in: tin tưởng\nbe made clear: được làm rõ", "structureEn": "have faith in: trust\nbe made clear: passive"}]$j$::jsonb),
  ('advanced', 'philosophy-ethics', 'Một lựa chọn có thể đem lại lợi ích tổng thể nhưng vẫn gây ra bất công nghiêm trọng cho một nhóm nhỏ.', $j$[{"text": "A choice may bring overall benefit while still causing serious injustice to a small group.", "structureVi": "may + V: có thể\nwhile still + V-ing: trong khi vẫn", "structureEn": "may + V: possibility\nwhile still + V-ing: simultaneously"}, {"text": "A decision can benefit most people and yet seriously wrong a small minority.", "structureVi": "can + V: có thể\nand yet: nhưng vẫn", "structureEn": "can + V: possibility\nand yet: despite that"}]$j$::jsonb),
  ('advanced', 'philosophy-ethics', 'Ý định tốt không tự động biện minh cho hậu quả có thể dự đoán của một hành động.', $j$[{"text": "Good intentions do not automatically justify the foreseeable consequences of an action.", "structureVi": "not automatically + V: không tự động\nforeseeable: có thể dự đoán", "structureEn": "not automatically + V: not by itself\nforeseeable: predictable"}, {"text": "Meaning well doesn't excuse the results of an act that could have been predicted.", "structureVi": "V-ing làm chủ ngữ: có ý tốt\nthat could have been predicted: mệnh đề quan hệ", "structureEn": "V-ing as subject: meaning well\nthat could have been predicted: relative clause"}]$j$::jsonb),
  ('advanced', 'philosophy-ethics', 'Trách nhiệm đạo đức trở nên phức tạp khi cá nhân phải lựa chọn giữa những nghĩa vụ đều đáng được coi trọng.', $j$[{"text": "Moral responsibility becomes complicated when individuals must choose between duties that each deserve respect.", "structureVi": "become + tính từ: trở nên\nduties that + V: nghĩa vụ mà", "structureEn": "become + adjective: change into\nduties that + V: relative clause"}, {"text": "Ethical duty gets complex when a person has to pick among obligations that all deserve to be taken seriously.", "structureVi": "get + tính từ: trở nên\ndeserve to be + V3: xứng đáng được", "structureEn": "get + adjective: become\ndeserve to be + V3: passive"}]$j$::jsonb),
  ('advanced', 'philosophy-ethics', 'Sự trung thực cần đi cùng lòng trắc ẩn để việc nói thật không trở thành cái cớ gây tổn thương không cần thiết.', $j$[{"text": "Honesty must be accompanied by compassion so that telling the truth doesn't become an excuse for unnecessary harm.", "structureVi": "be accompanied by: đi kèm\nso that + mệnh đề: để mà", "structureEn": "be accompanied by: go with\nso that + clause: purpose"}, {"text": "Being truthful has to go hand in hand with kindness, otherwise speaking honestly can excuse needless hurt.", "structureVi": "go hand in hand with: đi đôi với\notherwise + mệnh đề: nếu không thì", "structureEn": "go hand in hand with: accompany\notherwise + clause: or else"}]$j$::jsonb),
  ('advanced', 'philosophy-ethics', 'Một nguyên tắc chỉ đáng tin cậy khi chúng ta sẵn sàng áp dụng nó cả trong trường hợp bất lợi cho mình.', $j$[{"text": "A principle is trustworthy only when we are willing to apply it even in cases that go against our interests.", "structureVi": "only when + mệnh đề: chỉ khi\nbe willing to + V: sẵn sàng", "structureEn": "only when + clause: limiting condition\nbe willing to + V: ready to"}, {"text": "We can rely on a principle only if we are prepared to follow it even when it works against us.", "structureVi": "only if + mệnh đề: chỉ nếu\nwork against: bất lợi cho", "structureEn": "only if + clause: sole condition\nwork against: be disadvantageous to"}]$j$::jsonb),
  ('advanced', 'philosophy-ethics', 'Tự do cá nhân cần được cân nhắc với tác động mà hành vi của một người gây ra cho người khác.', $j$[{"text": "Individual freedom must be weighed against the impact a person's behavior has on others.", "structureVi": "be weighed against: được cân nhắc với\nthe impact (that) + mệnh đề: tác động", "structureEn": "be weighed against: balanced with\nthe impact (that)...: relative clause"}, {"text": "We should balance personal liberty with the effect our actions have on other people.", "structureVi": "balance A with B: cân bằng\nthe effect (that) our actions have: mệnh đề quan hệ", "structureEn": "balance A with B: weigh\nthe effect (that)...: relative clause"}]$j$::jsonb),
  ('advanced', 'philosophy-ethics', 'Việc đánh giá một quyết định nên xem xét cả quy trình lựa chọn lẫn kết quả cuối cùng.', $j$[{"text": "Evaluating a decision should consider both the process of choosing and the final outcome.", "structureVi": "Evaluating: V-ing làm chủ ngữ\nboth A and B: cả A lẫn B", "structureEn": "Evaluating: gerund subject\nboth A and B: two things"}, {"text": "To judge a decision fairly, we need to look at how it was made as well as what resulted.", "structureVi": "To + V: để\nA as well as B: cả A lẫn B", "structureEn": "To + V: purpose\nA as well as B: and also"}]$j$::jsonb),
  ('advanced', 'philosophy-ethics', 'Thừa nhận sự bất định không phải là từ bỏ phán đoán mà là giới hạn mức độ chắc chắn của kết luận.', $j$[{"text": "Acknowledging uncertainty is not giving up on judgment but limiting how certain our conclusions are.", "structureVi": "Acknowledging: V-ing làm chủ ngữ\nnot A but B: không phải A mà là B", "structureEn": "Acknowledging: gerund subject\nnot A but B: contrast"}, {"text": "Admitting that we are unsure doesn't mean abandoning our judgment; it means placing limits on how confident we are in our conclusions.", "structureVi": "doesn't mean + V-ing: không có nghĩa là\nhow + tính từ + mệnh đề: mức độ", "structureEn": "doesn't mean + V-ing: not imply\nhow + adjective + clause: degree"}]$j$::jsonb),
  ('advanced', 'philosophy-ethics', 'Công bằng đòi hỏi chúng ta xem xét hoàn cảnh khác nhau thay vì chỉ áp dụng một công thức giống nhau cho mọi người.', $j$[{"text": "Fairness requires us to consider different circumstances instead of applying one formula to everyone.", "structureVi": "require + người + to + V: đòi hỏi\ninstead of + V-ing: thay vì", "structureEn": "require + person + to + V: need someone to\ninstead of + V-ing: rather than"}, {"text": "Being fair means taking varying situations into account rather than using the same rule for all.", "structureVi": "mean + V-ing: có nghĩa là\nrather than + V-ing: thay vì", "structureEn": "mean + V-ing: involve\nrather than + V-ing: instead of"}]$j$::jsonb),
  ('advanced', 'philosophy-ethics', 'Suy ngẫm đạo đức có giá trị khi nó dẫn đến hành động nhất quán chứ không chỉ dừng lại ở lời nói.', $j$[{"text": "Ethical reflection is valuable when it leads to consistent action rather than stopping at words.", "structureVi": "lead to: dẫn đến\nrather than + V-ing: thay vì", "structureEn": "lead to: result in\nrather than + V-ing: instead of"}, {"text": "Thinking about ethics is worthwhile if it results in steady action instead of staying at the level of talk.", "structureVi": "result in: dẫn đến\ninstead of + V-ing: thay vì", "structureEn": "result in: lead to\ninstead of + V-ing: rather than"}]$j$::jsonb)
) as v(level, category, vietnamese, answers)
join public.prompts p
  on p.writing_type = 'sentence' and p.difficulty = v.level and p.category = v.category and p.prompt_text = v.vietnamese
on conflict (prompt_id) do nothing;
